 @{G='RETEA'; P=2; L='Prioritate jocuri in Windows (MMCSS: GPU/CPU pentru jocuri, fara limitare retea)'; Do={
    $sp = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
    RegSet $sp 'SystemResponsiveness' 10
    RegSet $sp 'NetworkThrottlingIndex' -1
    $gm = "$sp\Tasks\Games"
    RegSet $gm 'GPU Priority' 8; RegSet $gm 'Priority' 6
    RegSet $gm 'Scheduling Category' 'High' 'String'; RegSet $gm 'SFIO Priority' 'High' 'String' }},
 @{G='RETEA'; P=2; L='Cache DNS golit'; Do={ ipconfig /flushdns | Out-Null }},
 @{G='RETEA'; P=9; NoStar=$true; I='1F50B'; L='Placa de retea fara economie de energie (fara varfuri de ping)'; T='Opreste Energy Efficient Ethernet, Green Ethernet si oprirea placii de catre Windows pentru economie. Ajuta mai ales pe laptopuri. Conexiunea se reia cateva secunde la aplicare. REVINO pune totul la loc.'; Do={
    $nf = "$env:APPDATA\WinGameOptimizer\netadapter.json"
    $log = @(Read-JsonList $nf)
    $kw = '^(\*EEE|AdvancedEEE|EEELinkAdvertisement|EnableGreenEthernet|GigaLite|PowerSavingMode|ULPMode|EnablePowerManagement)$'
    $ch = 0
    foreach ($na in @(Get-NetAdapter -Physical | Where-Object { $_.Status -eq 'Up' })) {
        foreach ($pr in @(Get-NetAdapterAdvancedProperty -Name $na.Name -AllProperties -ErrorAction SilentlyContinue | Where-Object { $_.RegistryKeyword -match $kw })) {
            $old = [string]@($pr.RegistryValue)[0]
            if ($old -ne '0' -and (@($pr.ValidRegistryValues) -contains '0' -or -not $pr.ValidRegistryValues)) {
                Set-NetAdapterAdvancedProperty -Name $na.Name -RegistryKeyword $pr.RegistryKeyword -RegistryValue '0' -NoRestart -ErrorAction Stop
                if (-not ($log | Where-Object { $_.N -eq $na.Name -and $_.K -eq $pr.RegistryKeyword })) { $log += [pscustomobject]@{ N = $na.Name; K = $pr.RegistryKeyword; V = $old } }
                $ch++
            }
        }
        try { $pmg = Get-NetAdapterPowerManagement -Name $na.Name -ErrorAction Stop
              if ([string]$pmg.AllowComputerToTurnOffDevice -eq 'Enabled') {
                  Set-NetAdapterPowerManagement -Name $na.Name -AllowComputerToTurnOffDevice Disabled -NoRestart -ErrorAction Stop
                  if (-not ($log | Where-Object { $_.N -eq $na.Name -and $_.K -eq '#PM' })) { $log += [pscustomobject]@{ N = $na.Name; K = '#PM'; V = 'Enabled' } }
                  $ch++ } } catch {}
        if ($ch) { Restart-NetAdapter -Name $na.Name -ErrorAction SilentlyContinue }
    }
    New-Item (Split-Path $nf) -ItemType Directory -Force | Out-Null
    ConvertTo-Json -InputObject @($log) | Set-Content $nf -Encoding UTF8
    if (-not $ch) { throw 'nu era nimic de schimbat (setarile erau deja oprite sau placa nu le are)' } }},
 @{G='RETEA'; P=9; NoStar=$true; L='DNS Cloudflare 1.1.1.1 pe conexiunea activa (se aplica dupa restart)'; Do={
    $ifs = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces'
    foreach ($n in @(Get-NetIPConfiguration | Where-Object { $_.IPv4DefaultGateway -and $_.NetAdapter.Status -eq 'Up' })) {
        $k = "$ifs\$($n.NetAdapter.InterfaceGuid)"
        if (Test-Path $k) { RegSet $k 'NameServer' '1.1.1.1,1.0.0.1' 'String' }
    }
    ipconfig /flushdns | Out-Null }},

 @{G='CURATENIE DISC'; P=2; L='Cache shadere sters (se reface la primul joc, poate fi o mica sacadare)'; Do={
    foreach ($x in "$env:LOCALAPPDATA\D3DSCache", "$env:LOCALAPPDATA\NVIDIA\DXCache", "$env:LOCALAPPDATA\NVIDIA\GLCache", "$env:LOCALAPPDATA\AMD\DxCache", "$env:LOCALAPPDATA\AMD\GLCache") {
        if (Test-Path $x) { Remove-Item "$x\*" -Recurse -Force -ErrorAction SilentlyContinue } } }},
 @{G='CURATENIE DISC'; P=2; L='Cache Windows Update si Delivery Optimization sters'; Do={
    $was = @('wuauserv', 'bits' | Where-Object { (Get-Service $_ -ErrorAction SilentlyContinue).Status -eq 'Running' })
    foreach ($s in $was) { Stop-Service $s -Force -ErrorAction SilentlyContinue }
    Remove-Item "$env:WINDIR\SoftwareDistribution\Download\*" -Recurse -Force -ErrorAction SilentlyContinue
    foreach ($s in $was) { Start-Service $s -ErrorAction SilentlyContinue }
    try { Delete-DeliveryOptimizationCache -Force -ErrorAction Stop } catch {} }},
 @{G='CURATENIE DISC'; P=2; L='Componente Windows Update vechi curatate (DISM, dureaza cateva minute)'; Do={
    Dism.exe /Online /Cleanup-Image /StartComponentCleanup | Out-Null }},
 @{G='CURATENIE DISC'; P=2; L='Cache browsere sters (Chrome, Edge, Brave, Firefox) - inchide-le inainte'; Do={
    $ud = "$env:LOCALAPPDATA\Google\Chrome\User Data", "$env:LOCALAPPDATA\Microsoft\Edge\User Data", "$env:LOCALAPPDATA\BraveSoftware\Brave-Browser\User Data"
    $pats = @(); foreach ($u in $ud) { $pats += "$u\*\Cache\Cache_Data"; $pats += "$u\*\Code Cache"; $pats += "$u\*\GPUCache" }
    $pats += "$env:LOCALAPPDATA\Mozilla\Firefox\Profiles\*\cache2"
    foreach ($x in $pats) { Get-Item -Path $x -ErrorAction SilentlyContinue | ForEach-Object { Remove-Item "$($_.FullName)\*" -Recurse -Force -ErrorAction SilentlyContinue } } }},
 @{G='CURATENIE DISC'; P=2; L='NTFS: fara scriere la ultimul acces (mai putine scrieri pe disc, dupa restart)'; Do={
    RegSet 'HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem' 'NtfsDisableLastAccessUpdate' 1 }},
 @{G='CURATENIE DISC'; P=9; NoStar=$true; L='Sterge Windows.old (nu mai poti reveni la Windows-ul anterior)'; Do={
    $o = "$env:SystemDrive\Windows.old"
    if (Test-Path $o) { takeown /F $o /R /A /D Y | Out-Null; icacls $o /grant '*S-1-5-32-544:F' /T /C /Q | Out-Null
                        Remove-Item $o -Recurse -Force -ErrorAction SilentlyContinue } }},

 @{G='SERVICII'; P=9; NoStar=$true; L='Telemetrie: serviciile DiagTrack si dmwappushservice oprite'; Do={
    foreach ($s in 'DiagTrack', 'dmwappushservice') { if (Test-Path "HKLM:\SYSTEM\CurrentControlSet\Services\$s") { RegSet "HKLM:\SYSTEM\CurrentControlSet\Services\$s" 'Start' 4 } } }},
 @{G='SERVICII'; P=2; L='Servicii rar folosite pe Manual (Harti, Fax, Retail Demo, Control parental)'; Do={
    foreach ($s in 'MapsBroker', 'Fax', 'RetailDemo', 'WpcMonSvc') { if (Test-Path "HKLM:\SYSTEM\CurrentControlSet\Services\$s") { RegSet "HKLM:\SYSTEM\CurrentControlSet\Services\$s" 'Start' 3 } } }},

 @{G='FPS BOOST'; P=1; I='1F3AE'; L='Game Bar: fara popup-uri si buton controller'; T='Opreste popup-ul de pornire al Game Bar si deschiderea lui cu butonul Xbox al controllerului.'; Do={
    RegSet 'HKCU:\Software\Microsoft\GameBar' 'UseNexusForGameBarEnabled' 0
    RegSet 'HKCU:\Software\Microsoft\GameBar' 'ShowStartupPanel' 0 }},
 @{G='FPS BOOST'; P=2; I='1F5A5'; L='Optimizari jocuri windowed / borderless'; T='Windows 11: Optimizations for windowed games. Foloseste flip model, deci latenta si FPS mai bune in borderless (DX10/11).'; Do={
    $kk = 'HKCU:\Software\Microsoft\DirectX\UserGpuPreferences'
    $cur = ''; try { $cur = [string](Get-ItemProperty -Path $kk -Name DirectXUserGlobalSettings -ErrorAction Stop).DirectXUserGlobalSettings } catch {}
    if ($cur -and -not $cur.EndsWith(';')) { $cur += ';' }
    if ($cur -match 'SwapEffectUpgradeEnable=\d') { $new = $cur -replace 'SwapEffectUpgradeEnable=\d', 'SwapEffectUpgradeEnable=1' }
    else { $new = $cur + 'SwapEffectUpgradeEnable=1;' }
    RegSet $kk 'DirectXUserGlobalSettings' $new 'String' }},
 @{G='FPS BOOST'; P=2; I='1F4E1'; L='Delivery Optimization fara upload P2P'; T='Windows Update nu mai trimite fisiere catre alte PC-uri: mai putin trafic de retea si CPU in fundal.'; Do={
    RegSet 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization' 'DODownloadMode' 0 }},
 @{G='FPS BOOST'; NoStar=$true; P=3; I='1F9E0'; L='CPU 100% minim, boost agresiv, fara parking'; T='Procesorul nu mai coboara frecventa si nu mai adoarme nuclee. Atentie: consum si temperaturi mai mari si in idle.'; Do={
    powercfg /setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMIN 100
    powercfg /setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PERFBOOSTMODE 2
    powercfg /setacvalueindex SCHEME_CURRENT SUB_PROCESSOR CPMINCORES 100
    powercfg /setactive SCHEME_CURRENT }},
 @{G='FPS BOOST'; P=3; I='26A1'; L='Retea: Nagle oprit (jocuri TCP)'; T='Ping mai mic in jocurile care folosesc TCP (MMO, FiveM). Nu schimba FPS-ul.'; Do={
    foreach ($na in @(Get-NetAdapter -Physical | Where-Object { $_.Status -eq 'Up' })) {
        $kk = "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces\$($na.InterfaceGuid)"
        RegSet $kk 'TcpAckFrequency' 1; RegSet $kk 'TCPNoDelay' 1 } }},
 @{G='FPS BOOST'; P=2; I='1F3AF'; L='Prioritate pentru jocul din prim-plan'; T='Fereastra activa (jocul) primeste felii de timp CPU mai lungi decat aplicatiile din fundal. Win32PrioritySeparation = 38.'; Do={
    RegSet 'HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl' 'Win32PrioritySeparation' 38 }},
 @{G='FPS BOOST'; P=2; I='1F4C8'; L='Variable Refresh Rate si in jocurile windowed'; T='FreeSync / G-Sync functioneaza si in jocurile care nu au suport VRR propriu: mai putin tearing si stutter. Ai nevoie de monitor cu VRR.'; Do={
    $kk = 'HKCU:\Software\Microsoft\DirectX\UserGpuPreferences'
    $cur = ''; try { $cur = [string](Get-ItemProperty -Path $kk -Name DirectXUserGlobalSettings -ErrorAction Stop).DirectXUserGlobalSettings } catch {}
    if ($cur -and -not $cur.EndsWith(';')) { $cur += ';' }
    if ($cur -match 'VRROptimizeEnable=\d') { $new = $cur -replace 'VRROptimizeEnable=\d', 'VRROptimizeEnable=1' }
    else { $new = $cur + 'VRROptimizeEnable=1;' }
    RegSet $kk 'DirectXUserGlobalSettings' $new 'String' }},
 @{G='FPS BOOST'; P=2; I='2328'; L='Fara Sticky Keys / Filter Keys in jocuri'; T='Apasarea repetata pe Shift sau tinerea lui apasat nu mai deschide fereastra Sticky Keys peste joc.'; Do={
    RegSet 'HKCU:\Control Panel\Accessibility\StickyKeys' 'Flags' '506' 'String'
    RegSet 'HKCU:\Control Panel\Accessibility\Keyboard Response' 'Flags' '122' 'String'
    RegSet 'HKCU:\Control Panel\Accessibility\ToggleKeys' 'Flags' '58' 'String' }},
 @{G='FPS BOOST'; NoStar=$true; P=9; I='1F50C'; L='Optional: MSI mode pentru placa video'; T='Placa video foloseste Message Signaled Interrupts: latenta mai mica la intreruperi. Multe drivere noi il au deja pornit. Necesita restart. Daca apare ecran negru, porneste in Safe Mode si apasa REVINO.'; Do={
    $done = @()
    foreach ($a in @(Get-CimInstance Win32_VideoController | Where-Object { $_.PNPDeviceID -like 'PCI\*' -and $_.Name -notmatch 'Radeon\(TM\) Graphics$|Radeon Graphics$|Vega \d+ Graphics|Intel.*(UHD|Iris|HD Graphics)|Basic' })) {
        $k = "HKLM:\SYSTEM\CurrentControlSet\Enum\$($a.PNPDeviceID)\Device Parameters\Interrupt Management\MessageSignaledInterruptProperties"
        RegSet $k 'MSISupported' 1; $done += $a.Name
    }
    if (-not $done.Count) { throw 'nu am gasit o placa video dedicata PCIe' } }},
 @{G='FPS BOOST'; NoStar=$true; P=9; I='1F9EA'; L='Optional: MPO oprit (flicker / stutter)'; T='Opreste Multiplane Overlay. Foloseste-l DOAR daca ai flicker, ecran negru scurt sau stutter. Necesita restart.'; Do={
    RegSet 'HKLM:\SOFTWARE\Microsoft\Windows\Dwm' 'OverlayTestMode' 5 }},
 @{G='FPS BOOST'; NoStar=$true; P=9; I='23F1'; L='Optional: timer global Windows 11'; T='Restaureaza comportamentul vechi al timerului: frametime mai stabil in unele jocuri, dar consum mai mare.'; Do={
    RegSet 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel' 'GlobalTimerResolutionRequests' 1 }},
 @{G='FPS BOOST'; NoStar=$true; P=9; I='1F4FA'; L='Optional: fullscreen optimizations oprite'; T='Poate ajuta in jocuri vechi DX9/DX11. In jocurile moderne poate strica flip model, testeaza inainte.'; Do={
    $cc = 'HKCU:\System\GameConfigStore'
    RegSet $cc 'GameDVR_FSEBehaviorMode' 2; RegSet $cc 'GameDVR_HonorUserFSEBehaviorMode' 1
    RegSet $cc 'GameDVR_DXGIHonorFSEWindowsCompatible' 1; RegSet $cc 'GameDVR_EFSEFeatureFlags' 0 }},

 # P=9: nu este bifat de niciun profil, il activezi doar manual
 @{G='SECURITATE (OPTIONAL)'; P=9; L='Memory Integrity (HVCI) oprit: putin mai multe FPS, dar protectie mai mica (restart)'; Do={
    RegSet 'HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard\Scenarios\HypervisorEnforcedCodeIntegrity' 'Enabled' 0 }},
 @{G='SECURITATE (OPTIONAL)'; P=9; I='1F6E1'; L='VBS (Virtualization Based Security) oprit: cateva procente FPS, protectie mai mica (restart)'; T='Opreste securitatea bazata pe virtualizare. Pe unele PC-uri da 5-10% FPS in plus. Nu opreste Hyper-V sau WSL. Daca e blocat din UEFI, setarea nu are efect.'; Do={
    RegSet 'HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard' 'EnableVirtualizationBasedSecurity' 0
    RegSet 'HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard' 'RequirePlatformSecurityFeatures' 0 }},
 @{G='SECURITATE (OPTIONAL)'; P=9; I='1F4C2'; L='Windows Defender: excluderi pentru folderele cu jocuri'; T='Defender nu mai scaneaza folderele Steam, Epic, Xbox, Riot, GOG, EA, Ubisoft, Battle.net: mai putine sacadari la incarcare. Fisierele din ele nu mai sunt verificate. REVINO le scoate.'; Do={
    $roots = @()
    foreach ($v in @(Get-Volume -ErrorAction SilentlyContinue | Where-Object { $_.DriveLetter -and $_.DriveType -eq 'Fixed' })) {
        $dl = "$($v.DriveLetter):"
        $roots += "$dl\XboxGames", "$dl\SteamLibrary\steamapps\common", "$dl\Games", "$dl\Epic Games", "$dl\Riot Games", "$dl\GOG Games"
    }
    foreach ($pf in $env:ProgramFiles, ${env:ProgramFiles(x86)}) {
        $roots += "$pf\Steam\steamapps\common", "$pf\Epic Games", "$pf\Riot Games", "$pf\GOG Galaxy\Games", "$pf\EA Games", "$pf\Electronic Arts", "$pf\Ubisoft\Ubisoft Game Launcher\games", "$pf\Battle.net", "$pf\Rockstar Games"
    }
    # biblioteci Steam suplimentare din libraryfolders.vdf
    foreach ($pf in $env:ProgramFiles, ${env:ProgramFiles(x86)}) {
        $vdf = "$pf\Steam\steamapps\libraryfolders.vdf"
        if (Test-Path $vdf) { foreach ($m in [regex]::Matches((Get-Content $vdf -Raw), '"path"\s+"([^"]+)"')) { $roots += ($m.Groups[1].Value -replace '\\\\', '\') + '\steamapps\common' } }
    }
    $found = @($roots | Where-Object { $_ -and (Test-Path -LiteralPath $_) } | ForEach-Object { (Resolve-Path -LiteralPath $_).Path } | Select-Object -Unique)
    if (-not $found.Count) { throw 'nu am gasit foldere cu jocuri' }
    $have = @(); try { $have = @((Get-MpPreference -ErrorAction Stop).ExclusionPath) } catch { throw 'Windows Defender nu raspunde (alt antivirus activ?)' }
    $add = @($found | Where-Object { $have -notcontains $_ })
    if ($add.Count) { Add-MpPreference -ExclusionPath $add -ErrorAction Stop }
    # tinem minte ce am adaugat noi, ca REVINO sa scoata doar acestea
    $df = "$env:APPDATA\WinGameOptimizer\defender.json"
    $prev = @(Read-JsonList $df)
    New-Item (Split-Path $df) -ItemType Directory -Force | Out-Null
    ConvertTo-Json -InputObject @(@($prev + $add) | Select-Object -Unique) | Set-Content $df -Encoding UTF8
    if (-not $add.Count) { throw "erau deja excluse: $($found -join ', ')" } }}
)

# ---------- Curatare aplicatii (dupa Winhance) ----------
# Format: Nume|pachet1,pachet2|flags   S = bifat la tine (steluta, intra la Maxim)   P = definitiv   - = nimic
$star = [string][char]0x2605
$appGroup = "CURATARE APLICATII   ($star = bifat la tine in Winhance)"
$appList = @(
 '3D Viewer|Microsoft.Microsoft3DViewer|S',
 'AI Workload Packages|WindowsWorkload.*|SP',
 'Windows AI Experience|MicrosoftWindows.Client.AIX|SP',
 'Windows Copilot Client|MicrosoftWindows.Client.CoPilot|SP',
 'Bing Search|Microsoft.BingSearch|S',
 'Cortana|Microsoft.549981C3F5F10|SP',
 'Edge Game Assist|Microsoft.Edge.GameAssist|SP',
 'Feedback Hub|Microsoft.WindowsFeedbackHub|S',
 'Get Help|Microsoft.GetHelp|S',
 'Mail and Calendar|microsoft.windowscommunicationsapps|S',
 'Maps|Microsoft.WindowsMaps|SP',
 'Microsoft Family Safety|MicrosoftCorporationII.MicrosoftFamily|S',
 'Microsoft News|Microsoft.BingNews|S',
 'Microsoft Teams|MSTeams,MicrosoftTeams|S',
 'Mixed Reality Portal|Microsoft.MixedReality.Portal|S',
 'MS 365 Copilot (Office Hub)|Microsoft.MicrosoftOfficeHub|S',
 'MSN Weather|Microsoft.BingWeather|S',
 'OneNote|Microsoft.Office.OneNote|S',
 'Outlook for Windows|Microsoft.OutlookForWindows|S',
 'Paint 3D|Microsoft.MSPaint|SP',
 'People|Microsoft.People|SP',
 'Quick Assist|MicrosoftCorporationII.QuickAssist|S',
 'Skype|Microsoft.SkypeApp|SP',
 'Solitaire Collection|Microsoft.MicrosoftSolitaireCollection|S',
 'Sticky Notes|Microsoft.MicrosoftStickyNotes|S',
 'Tips|Microsoft.Getstarted|SP',
 'To Do|Microsoft.Todos|S',
 'Camera|Microsoft.WindowsCamera|-',
 'Media Player|Microsoft.ZuneMusic|-',
 'Movies and TV|Microsoft.ZuneVideo|-',
 'Photos|Microsoft.Windows.Photos|-',
 'Snipping Tool|Microsoft.ScreenSketch|-',
 'Notepad|Microsoft.WindowsNotepad|-',
 'Paint|Microsoft.Paint|-',
 'Calculator|Microsoft.WindowsCalculator|-',
 'Alarms and Clock|Microsoft.WindowsAlarms|-',
 'Sound Recorder|Microsoft.WindowsSoundRecorder|-',
 'Clipchamp|Clipchamp.Clipchamp|-',
 'Phone Link|Microsoft.YourPhone|-',
 'Power Automate|Microsoft.PowerAutomateDesktop|-'
)
$appTweaks = @()
foreach ($line in $appList) {
    $f = $line -split '\|'
    $isStar = $f[2] -match 'S'
    $lbl = $(if ($isStar) { "$star " } else { '' }) + $f[0] + $(if ($f[2] -match 'P') { '  [definitiv]' } else { '' })
    $appTweaks += @{ G = $appGroup; P = $(if ($isStar) { 3 } else { 9 }); L = $lbl; K = ($f[1] -split ','); Do = { param($t) Remove-AppPkg $t.K } }
}
$appTweaks += @{ G = $appGroup; P = 3; L = "$star OneDrive (fisierele locale raman pe PC)"; Do = {
    Stop-Process -Name OneDrive -Force -ErrorAction SilentlyContinue
    $x = "$env:SystemRoot\SysWOW64\OneDriveSetup.exe"
    if (-not (Test-Path $x)) { $x = "$env:SystemRoot\System32\OneDriveSetup.exe" }
    if (Test-Path $x) { Start-Process $x '/uninstall' -Wait } } }
# grupa de aplicatii vine inainte de SECURITATE (OPTIONAL)
$tweaks = @($tweaks | Where-Object { $_.G -notlike 'SECURITATE*' }) + $appTweaks + @($tweaks | Where-Object { $_.G -like 'SECURITATE*' })

# ---------- Privacy AI (dupa Winhance, toate pe OFF) ----------
# Format: Grupa|Nume|IconHex|Profil(2=LOW+ULTRA, 3=doar ULTRA)|cale,nume,valoare;cale,nume,valoare
$pt = @{ W = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsAI'; E = 'HKLM:\SOFTWARE\Policies\Microsoft\Edge'
         P = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Paint'; CC = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent'
         C = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\CapabilityAccessManager\ConsentStore'
         M = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\CapabilityAccessManager\ConsentStore\microphone'
         S = 'HKCU:\Software\Microsoft\Windows\Shell\Copilot'; I = 'HKCU:\Software\Microsoft\Input\Settings'
         O = 'HKCU:\Software\Policies\Microsoft\office\16.0\common\privacy' }
$WA = 'PRIVACY: WINDOWS AI'; $EA = 'PRIVACY: EDGE AI'; $OA = 'PRIVACY: OFFICE AI'
$aiList = @(
 "$WA|AI Data Analysis|1F9E0|2|W,DisableAIDataAnalysis,1",
 "$WA|Recall Enablement|1F6AB|2|W,AllowRecallEnablement,0",
 "$WA|Recall Saving Snapshots|1F4F7|2|W,TurnOffSavingSnapshots,1",
 "$WA|Click to Do|1F5B1|2|W,DisableClickToDo,1",
 "$WA|AI Settings Agent|2699|2|W,DisableSettingsAgent,1",
 "$WA|AI Agent Connectors|1F50C|2|W,DisableAgentConnectors,1",
 "$WA|AI Agent Workspaces|1F5A5|2|W,DisableAgentWorkspaces,1",
 "$WA|Remote AI Agent Connectors|1F310|2|W,DisableRemoteAgentConnectors,1",
 "$WA|Copilot Availability (Windows Shell)|1F6AB|2|S,IsCopilotAvailable,0",
 "$WA|Bing Chat Eligibility|1F4AC|2|S\BingChat,IsUserEligible,0",
 "$WA|Generative AI Access|2728|2|C\generativeAI,Value,Deny",
 "$WA|System AI Models Access (strica OCR in Snipping Tool)|1F9E9|3|C\systemAIModels,Value,Deny",
 "$WA|Copilot Microphone Access|1F3A4|2|M\Microsoft.Copilot_8wekyb3d8bbwe,Value,Deny;M\Microsoft.MicrosoftOfficeHub_8wekyb3d8bbwe,Value,Deny",
 "$WA|Paint AI Image Creator|1F5BC|2|P,DisableImageCreator,1",
 "$WA|Paint AI Cocreator|1F3A8|2|P,DisableCocreator,1",
 "$WA|Paint Generative Fill|1F58C|2|P,DisableGenerativeFill,1",
 "$WA|Paint Generative Erase|1F9FD|2|P,DisableGenerativeErase,1",
 "$WA|Paint Remove Background|2702|2|P,DisableRemoveBackground,1",
 "$WA|Input Insights|2328|2|I,InsightsEnabled,0",
 "$WA|AI Consumer Content|1F464|2|CC,DisableConsumerAccountStateContent,1",
 "$EA|Edge Copilot CDP Page Context|1F310|2|E,CopilotCDPPageContext,0",
 "$EA|Edge Copilot Page Context|1F4C4|2|E,CopilotPageContext,0",
 "$EA|Edge Copilot Sidebar|1F4D1|2|E,HubsSidebarEnabled,0",
 "$EA|Edge Entra Copilot Page Context|1F6E1|2|E,EdgeEntraCopilotPageContext,0",
 "$EA|Edge M365 Copilot Chat Icon|1F4AC|2|E,Microsoft365CopilotChatIconEnabled,0",
 "$EA|Edge AI History Search|1F552|2|E,EdgeHistoryAISearchEnabled,0",
 "$EA|Edge Inline AI Compose|270F|2|E,ComposeInlineEnabled,0",
 "$EA|Edge Local AI Model Settings|1F9E0|2|E,GenAILocalFoundationalModelSettings,1",
 "$EA|Edge Built-in AI APIs|1F50C|2|E,BuiltInAIAPIsEnabled,0",
 "$EA|Edge AI Generated Themes|1F3A8|2|E,AIGenThemesEnabled,0",
 "$EA|Edge DevTools AI|1F6E0|2|E,DevToolsGenAiSettings,2",
 "$OA|Office Connected Services|2601|2|O,controllerconnectedservicesenabled,2;O,usercontentdisabled,2;O,downloadcontentdisabled,2"
)
$aiTweaks = @()
foreach ($line in $aiList) {
    $f = $line -split '\|'
    $ents = @($f[4] -split ';' | ForEach-Object {
        $p = $_ -split ',', 3
        $tok, $sub = $p[0] -split '\\', 2
        $path = $pt[$tok] + $(if ($sub) { "\$sub" } else { '' })
        $isNum = $p[2] -match '^\d+$'
        , @($path, $p[1], $(if ($isNum) { [int]$p[2] } else { $p[2] }), $(if ($isNum) { 'DWord' } else { 'String' }))
    })
    $aiTweaks += @{ G = $f[0]; S = $true; P = [int]$f[3]; L = $f[1]; I = $f[2]; E = $ents; X = ($f[1] -eq 'Recall Enablement')
                    Do = { param($t)
                        foreach ($e in $t.E) { RegSet $e[0] $e[1] $e[2] $e[3] }
                        if ($t.X) { try { Disable-WindowsOptionalFeature -Online -FeatureName Recall -NoRestart -ErrorAction Stop | Out-Null } catch {} } } }
}
$tweaks = @($tweaks | Where-Object { $_.G -notlike 'CURATARE*' -and $_.G -notlike 'SECURITATE*' }) + $aiTweaks +
          @($tweaks | Where-Object { $_.G -like 'CURATARE*' }) + @($tweaks | Where-Object { $_.G -like 'SECURITATE*' })

# ---------- Interfata: 5AM Optimizer ----------
Add-Type -AssemblyName PresentationCore, WindowsBase
$xaml = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="5AM Optimizer" Width="940" Height="900" MinWidth="720" MinHeight="640"
        WindowStartupLocation="CenterScreen" FontFamily="Segoe UI">
  <Window.Background>
    <RadialGradientBrush Center="0.5,0" RadiusX="1.1" RadiusY="0.9" GradientOrigin="0.5,0">
      <GradientStop Color="#3A0612" Offset="0"/><GradientStop Color="#0A0306" Offset="0.55"/><GradientStop Color="#030102" Offset="1"/>
    </RadialGradientBrush>
  </Window.Background>
  <Window.Resources>
    <Style TargetType="CheckBox">
      <Setter Property="Template"><Setter.Value>
        <ControlTemplate TargetType="CheckBox">
          <Border x:Name="Card" CornerRadius="12" Background="#120609" BorderBrush="#34101A" BorderThickness="1" Padding="11" Cursor="Hand">
            <Grid>
              <ContentPresenter/>
              <Ellipse x:Name="Dot" Width="10" Height="10" Fill="#3A1F27" HorizontalAlignment="Right" VerticalAlignment="Top"/>
            </Grid>
          </Border>
          <ControlTemplate.Triggers>
            <Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Card" Property="BorderBrush" Value="#FF7A93"/></Trigger>
            <Trigger Property="IsChecked" Value="True">
              <Setter TargetName="Card" Property="BorderBrush" Value="#FF2E4D"/>
              <Setter TargetName="Card" Property="Background" Value="#2A0812"/>
              <Setter TargetName="Dot" Property="Fill" Value="#FF2E4D"/>
              <Setter TargetName="Card" Property="Effect"><Setter.Value>
                <DropShadowEffect Color="#FF2E4D" BlurRadius="18" ShadowDepth="0" Opacity="0.65"/></Setter.Value></Setter>
            </Trigger>
          </ControlTemplate.Triggers>
        </ControlTemplate></Setter.Value></Setter>
    </Style>
    <Style x:Key="Pill" TargetType="Button">
      <Setter Property="Foreground" Value="White"/><Setter Property="Cursor" Value="Hand"/>
      <Setter Property="Template"><Setter.Value>
        <ControlTemplate TargetType="Button">
          <Border x:Name="B" CornerRadius="14" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}"
                  BorderThickness="{TemplateBinding BorderThickness}" Padding="{TemplateBinding Padding}">
            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
          </Border>
          <ControlTemplate.Triggers>
            <Trigger Property="IsMouseOver" Value="True"><Setter TargetName="B" Property="Opacity" Value="0.85"/></Trigger>
            <Trigger Property="IsEnabled" Value="False"><Setter TargetName="B" Property="Opacity" Value="0.4"/></Trigger>
          </ControlTemplate.Triggers>
        </ControlTemplate></Setter.Value></Setter>
    </Style>
  </Window.Resources>
  <Grid>
    <Grid Margin="22">
      <Grid.RowDefinitions>
        <RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/>
        <RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="90"/>
      </Grid.RowDefinitions>

      <Grid Margin="0,0,0,12">
        <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
        <Grid x:Name="ScoreBox" Grid.Column="2" Width="112" Height="112" Cursor="Hand" Background="Transparent" ToolTip="Scor 5AM: apasa ca sa vezi ce mai poti imbunatati">
          <Ellipse Stroke="#2A0812" StrokeThickness="10"/>
          <Path x:Name="ScoreArc" Stroke="#FF2E4D" StrokeThickness="10" StrokeStartLineCap="Round" StrokeEndLineCap="Round">
