        </Image>
      </Grid>

      <StackPanel Grid.Row="1">
        <Border x:Name="UpdBanner" Visibility="Collapsed" CornerRadius="10" Background="#1E0A10" BorderBrush="#FF2E4D" BorderThickness="1" Padding="12,8" Margin="0,0,0,8">
          <Grid>
            <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
            <TextBlock x:Name="UpdText" Foreground="#FFE4EA" FontSize="12.5" VerticalAlignment="Center" TextWrapping="Wrap"/>
            <Button x:Name="UpdBtn" Grid.Column="1" Style="{StaticResource Pill}" Content="ACTUALIZEAZA" Padding="14,7" Margin="10,0,0,0" Background="#FF2E4D" Visibility="Collapsed"/>
          </Grid>
        </Border>
        <UniformGrid x:Name="Dash" Columns="6"/>
        <Border x:Name="DetailBox" Visibility="Collapsed" CornerRadius="10" Background="#1A060C" BorderBrush="#4A1220" BorderThickness="1" Padding="12,9" Margin="0,4,0,0">
          <TextBlock x:Name="DetailText" FontSize="12" Foreground="#FFB7C5" TextWrapping="Wrap"/>
        </Border>
      </StackPanel>

      <StackPanel Grid.Row="2" Orientation="Horizontal" Margin="0,14,0,2">
        <TextBlock Text="SELECTIE RAPIDA" FontSize="11" FontWeight="Bold" Foreground="#FF7A93" VerticalAlignment="Center" Margin="2,0,12,0"/>
        <Button x:Name="BtnRec" Style="{StaticResource Pill}" Content="&#x2605; CU STELUTA" Background="#1A070D" BorderBrush="#FF2E4D" BorderThickness="1" FontSize="11" Padding="14,6" Margin="0,0,8,0"/>
        <Button x:Name="BtnAll" Style="{StaticResource Pill}" Content="TOT" Background="#1A070D" BorderBrush="#4A1220" BorderThickness="1" FontSize="11" Padding="14,6" Margin="0,0,8,0"/>
        <Button x:Name="BtnNone" Style="{StaticResource Pill}" Content="NIMIC" Background="#1A070D" BorderBrush="#4A1220" BorderThickness="1" FontSize="11" Padding="14,6"/>
        <TextBlock Text="apasa pe un folder ca sa vezi ce e inauntru" FontSize="11" Foreground="#8A6A72" VerticalAlignment="Center" Margin="16,0,0,0"/>
      </StackPanel>

      <Grid Grid.Row="3" Margin="0,8,0,0">
        <ScrollViewer x:Name="FolderScroll" VerticalScrollBarVisibility="Hidden" HorizontalScrollBarVisibility="Disabled">
          <WrapPanel x:Name="Folders"/>
        </ScrollViewer>
        <Grid x:Name="FolderView" Visibility="Collapsed">
          <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
          <Grid Margin="0,0,0,10">
            <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
            <Button x:Name="BtnBack" Style="{StaticResource Pill}" Content="&#x2190;  INAPOI" Background="#2A1219" Padding="14,7" FontSize="12" Margin="0,0,14,0"/>
            <TextBlock x:Name="ViewTitle" Grid.Column="1" FontSize="14" FontWeight="Bold" VerticalAlignment="Center" TextTrimming="CharacterEllipsis"/>
            <Button x:Name="BtnGrpAll" Grid.Column="2" Style="{StaticResource Pill}" Content="BIFEAZA TOT" Background="#1A070D" BorderBrush="#4A1220" BorderThickness="1" FontSize="11" Padding="12,6" Margin="0,0,8,0"/>
            <Button x:Name="BtnGrpNone" Grid.Column="3" Style="{StaticResource Pill}" Content="DEBIFEAZA TOT" Background="#1A070D" BorderBrush="#4A1220" BorderThickness="1" FontSize="11" Padding="12,6"/>
          </Grid>
