      <ProgressBar x:Name="Bar" Grid.Row="5" Height="5" Margin="0,10,0,8" Background="#1F0A10" Foreground="#FF2E4D" BorderThickness="0" Minimum="0" Maximum="1" Value="0"/>
      <Border Grid.Row="6" CornerRadius="12" Background="#060203" BorderBrush="#3A0F1A" BorderThickness="1">
        <TextBox x:Name="LogBox" IsReadOnly="True" Background="Transparent" Foreground="#FFB7C5" FontFamily="Consolas" FontSize="11"
                 BorderThickness="0" Padding="10" VerticalScrollBarVisibility="Hidden" TextWrapping="Wrap"/>
      </Border>
    </Grid>
    <Canvas x:Name="Fx" IsHitTestVisible="False"/>
  </Grid>
</Window>
'@
$xaml = [regex]::Replace($xaml, '#[0-9A-Fa-f]{6}\b', { param($mm) Convert-ThemeColor $mm.Value })
$w = [Windows.Markup.XamlReader]::Parse($xaml)
$LogBox = $w.FindName('LogBox'); $Bar = $w.FindName('Bar'); $Count = $w.FindName('Count')
$Dash = $w.FindName('Dash'); $Title = $w.FindName('Title'); $Fx = $w.FindName('Fx')
$DetailBox = $w.FindName('DetailBox'); $DetailText = $w.FindName('DetailText')
$Folders = $w.FindName('Folders'); $FolderScroll = $w.FindName('FolderScroll'); $FolderView = $w.FindName('FolderView')
$ViewScroll = $w.FindName('ViewScroll'); $ViewTitle = $w.FindName('ViewTitle')
$BtnBack = $w.FindName('BtnBack'); $BtnGrpAll = $w.FindName('BtnGrpAll'); $BtnGrpNone = $w.FindName('BtnGrpNone')
$BtnRec = $w.FindName('BtnRec'); $BtnAll = $w.FindName('BtnAll'); $BtnNone = $w.FindName('BtnNone')
$w.FindName('Logo').Source = $script:logoBmp
$BtnApply = $w.FindName('BtnApply'); $BtnRevert = $w.FindName('BtnRevert')
$w.FindName('Sub').Text = "AI OFF  |  MAX PERFORMANCE  |  GAMING EDITION  |  v$AppVersion"
$bc = New-Object Windows.Media.BrushConverter
function Br($h) { $bc.ConvertFromString((Convert-ThemeColor $h)) }
function Emo($c) { [char]::ConvertFromUtf32($c) }

# ---------- Iconite 3D (Microsoft Fluent Emoji, licenta MIT) ----------
# @@ICONPACK@@ build-ul de pe GitHub inlocuieste linia urmatoare cu iconitele din assets\icons incorporate in exe
$script:iconPack = @{}
$script:iconCache = @{}
function New-Bitmap($bytes) {
    $b = New-Object Windows.Media.Imaging.BitmapImage
    $b.BeginInit(); $b.StreamSource = New-Object IO.MemoryStream (, $bytes); $b.CacheOption = 'OnLoad'; $b.EndInit(); $b.Freeze(); $b
}
function Get-IconBitmap($cp) {
    if ($script:iconCache.ContainsKey($cp)) { return $script:iconCache[$cp] }
    $bmp = $null
    try {
        if ($script:iconPack[$cp]) { $bmp = New-Bitmap ([Convert]::FromBase64String($script:iconPack[$cp])) }
        elseif ($PSCommandPath) {
            $f = Join-Path (Split-Path $PSCommandPath) "assets\icons\$cp.png"
            if (Test-Path -LiteralPath $f) { $bmp = New-Bitmap ([IO.File]::ReadAllBytes($f)) }
        }
    } catch { $bmp = $null }
    $script:iconCache[$cp] = $bmp; $bmp
}
# Imagine 3D daca exista, altfel emoji-ul obisnuit
function Icon($emo, $size) {
    $cp = ''; try { $cp = '{0:x}' -f [char]::ConvertToUtf32([string]$emo, 0) } catch {}
    $bmp = $(if ($cp) { Get-IconBitmap $cp })
    if ($bmp) {
        $im = New-Object Windows.Controls.Image; $im.Source = $bmp; $im.Width = $size; $im.Height = $size; $im.HorizontalAlignment = 'Left'
        [Windows.Media.RenderOptions]::SetBitmapScalingMode($im, [Windows.Media.BitmapScalingMode]::HighQuality)
        $im.Effect = New-Object Windows.Media.Effects.DropShadowEffect -Property @{ Color = [Windows.Media.Color]::FromRgb(0, 0, 0); BlurRadius = 10; ShadowDepth = 3; Opacity = 0.55 }
        return $im
    }
    $t = TB ([string]$emo) ([double]$size * 0.8) '#FFFFFF' $false; $t.FontFamily = 'Segoe UI Emoji'; $t
}
function TB($t, $s, $c, $b) { $x = New-Object Windows.Controls.TextBlock; $x.Text = $t; $x.FontSize = $s; $x.Foreground = (Br $c); if ($b) { $x.FontWeight = 'Bold' }; $x }
function Say($m) { $LogBox.AppendText("$m`r`n"); $LogBox.ScrollToEnd(); $w.Dispatcher.Invoke([Action]{}, [Windows.Threading.DispatcherPriority]::Background) }

# ---------- Pictograme ----------
function Get-Icon($t) {
    if ($t.I) { return Emo ([Convert]::ToInt32($t.I, 16)) }
    if ($t.G -like 'CURATARE*') {
        switch -Regex ($t.L) {
            'Mail|Outlook'                                          { return Emo 0x1F4E7 }
            'Teams|Skype|Phone|People'                              { return Emo 0x1F4AC }
            'Weather|News|Maps|Bing'                                { return Emo 0x1F30D }
            'Photos|Camera|Paint|3D|Snipping|Clipchamp|Movies|Media' { return Emo 0x1F3A8 }
            'Solitaire'                                             { return Emo 0x1F0CF }
            'Copilot|AI|Cortana'                                    { return Emo 0x1F916 }
            'OneDrive|OneNote|Notes|To Do'                          { return Emo 0x2601 }
            default                                                 { return Emo 0x1F4E6 }
        }
    }
    $m = @{ 'AI SI COPILOT' = 0x1F916; 'PRIVACY' = 0x1F512; 'POWER PLAN' = 0x26A1; 'GPU SI GAMING' = 0x1F3AE; 'PERFORMANTA WINDOWS' = 0x1F680; 'SECURITATE (OPTIONAL)' = 0x1F6E1; 'RETEA' = 0x1F4E1; 'CURATENIE DISC' = 0x1F9F9; 'SERVICII' = 0x1F527; 'FPS BOOST' = 0x1F525 }
    Emo $m[$t.G]
}

# ---------- Dashboard hardware (chip-uri; detaliile apar la click) ----------
$ui = @{}; $script:selKey = $null
function Show-Detail {
    if (-not $script:selKey) { $DetailBox.Visibility = 'Collapsed' }
    else {
        $u = $ui[$script:selKey]
        $DetailText.Text = $u.N + $(if ($u.L) { "`n`n" + $u.L } else { '' })
        $DetailBox.Visibility = 'Visible'
    }
    foreach ($k in @($ui.Keys)) { if ($ui[$k].B -is [Windows.Controls.Border]) { $ui[$k].B.BorderBrush = Br $(if ($k -eq $script:selKey) { '#FF2E4D' } else { '#3A0F1A' }) } }
}
foreach ($k in 'CPU', 'GPU', 'RAM', 'DISCURI', 'ANALIZA', 'SFATURI') {
    $b = New-Object Windows.Controls.Border
    $b.CornerRadius = 12; $b.Padding = '11,8'; $b.Margin = '0,0,8,0'; $b.BorderThickness = 1; $b.Cursor = [Windows.Input.Cursors]::Hand
    $b.Background = Br '#12060A'; $b.BorderBrush = Br '#3A0F1A'; $b.Tag = $k
    $sp = New-Object Windows.Controls.StackPanel
    $v = TB '...' 14 '#FFE4EA' $true; $v.Margin = '0,2,0,0'; $v.TextTrimming = 'CharacterEllipsis'
    $sp.Children.Add((TB $k 10.5 '#FF2E4D' $true)) | Out-Null; $sp.Children.Add($v) | Out-Null
    $spk = $null
    if ($k -in 'CPU', 'GPU', 'RAM') {
        $cv = New-Object Windows.Controls.Canvas; $cv.Height = 22; $cv.Margin = '0,5,0,0'; $cv.ClipToBounds = $true
        $ar = New-Object Windows.Shapes.Polygon; $ar.Opacity = 0.28
        $ar.Fill = New-Object Windows.Media.LinearGradientBrush((Br '#FF2E4D').Color, [Windows.Media.Colors]::Transparent, 90)
        $pl = New-Object Windows.Shapes.Polyline; $pl.Stroke = Br '#FF4D6D'; $pl.StrokeThickness = 1.6; $pl.StrokeLineJoin = 'Round'
        $cv.Children.Add($ar) | Out-Null; $cv.Children.Add($pl) | Out-Null; $sp.Children.Add($cv) | Out-Null
        $spk = @{ C = $cv; L = $pl; A = $ar; H = New-Object Collections.ArrayList }
    }
    $b.Child = $sp; $Dash.Children.Add($b) | Out-Null
    $b.Add_MouseLeftButtonUp({ $kk = $args[0].Tag; $script:selKey = $(if ($script:selKey -eq $kk) { $null } else { $kk }); Show-Detail })
    $ui[$k] = @{ B = $b; V = $v; N = ''; L = ''; Sp = $spk }
}
function Push-Spark($k, $val) {
    $s = $ui[$k].Sp; if (-not $s -or $null -eq $val) { return }
    [void]$s.H.Add([double][math]::Max(0, [math]::Min(100, $val))); while ($s.H.Count -gt 45) { $s.H.RemoveAt(0) }
    $wd = $s.C.ActualWidth; $hh = 22; if ($wd -lt 10 -or $s.H.Count -lt 2) { return }
    $step = $wd / 44; $n = $s.H.Count
    $pts = New-Object Windows.Media.PointCollection
    for ($i = 0; $i -lt $n; $i++) { $pts.Add((New-Object Windows.Point(($wd - ($n - 1 - $i) * $step), ($hh - 1 - $s.H[$i] / 100.0 * ($hh - 3))))) }
    $s.L.Points = $pts
    $ap = New-Object Windows.Media.PointCollection; foreach ($pt in $pts) { $ap.Add($pt) }
    $ap.Add((New-Object Windows.Point($wd, $hh))); $ap.Add((New-Object Windows.Point(($wd - ($n - 1) * $step), $hh))); $s.A.Points = $ap
}
$cp = Get-CimInstance Win32_Processor | Select-Object -First 1
$ui.CPU.N = "$($cp.Name.Trim())`n$($cp.NumberOfCores) nuclee / $($cp.NumberOfLogicalProcessors) thread-uri"
function Get-GpuInfo {
    function Rs($v) {
        if ($null -eq $v) { return '' }
        if ($v -is [byte[]]) { $v = [Text.Encoding]::Unicode.GetString($v) }
        ([string]$v).Trim([char]0, ' ')
    }
    $cls = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e968-e325-11cd-be10-08002be10318}'
    # Fiecare subcheie 0000, 0001... e citita separat: subcheia "Properties" e protejata de Windows
    # si, daca lista se citeste dintr-o data, eroarea ei oprea toata citirea (VRAM ramanea la 4 GB).
    $regs = @()
    for ($i = 0; $i -lt 32; $i++) {
        $kp = Join-Path $cls ('{0:D4}' -f $i)
        try { $it = Get-ItemProperty -LiteralPath $kp -ErrorAction Stop; if ($it.DriverDesc) { $regs += $it } } catch {}
    }
    $out = @()
    foreach ($a in $script:gpuAdapters) {
        $r = $regs | Where-Object { $_.DriverDesc -eq $a.Name } | Select-Object -First 1
        $vram = 0.0; $mt = ''; $adr = ''
        if ($r) {
            try { $q = $r.'HardwareInformation.qwMemorySize'
                  if ($q -is [byte[]]) { $q = [BitConverter]::ToUInt64($q, 0) }
                  if ($q) { $vram = [double]$q } } catch {}
            $mt = Rs $r.'HardwareInformation.MemoryType'
            if ($mt -notmatch '^[A-Za-z0-9 \-\.]{2,20}$') { $mt = '' }
            $adr = Rs $r.RadeonSoftwareVersion
            if ($adr -notmatch '^[0-9\.]{3,20}$') { $adr = '' }
        }
        # rezerva pentru NVIDIA: memoria raportata direct de driver
        if ($vram -le 4GB -and $a.Name -match 'NVIDIA' -and (Get-Command nvidia-smi -ErrorAction SilentlyContinue)) {
            try {
                foreach ($ln in @(& nvidia-smi --query-gpu=name,memory.total --format=csv,noheader,nounits 2>$null)) {
                    $nm, $mb = ([string]$ln) -split ',\s*'
                    if ($nm -and $a.Name -like "*$($nm.Trim())*" -and [int]$mb -gt 0) { $vram = [double]$mb * 1MB; break }
                }
            } catch {}
        }
        # ultima varianta: AdapterRAM (limitat de Windows la 4 GB)
        if ($vram -le 0 -and $a.AdapterRAM) { $vram = [double]$a.AdapterRAM }
        $vtxt = if ($vram -le 0) { 'VRAM ?' } elseif ($vram -lt 2GB) { '{0:N0} MB' -f ($vram / 1MB) } else { '{0:N0} GB' -f ($vram / 1GB) }
        if ($mt) { $vtxt += " $mt" }
        $drv = "driver $($a.DriverVersion)"
        if ($adr) { $drv += " (Adrenalin $adr)" }
        if ($a.DriverDate) { try { $drv += ", din $(([datetime]$a.DriverDate).ToString('yyyy-MM-dd'))" } catch {} }
        $res = ''
        if ($a.CurrentHorizontalResolution) { $res = "$($a.CurrentHorizontalResolution)x$($a.CurrentVerticalResolution) @ $($a.CurrentRefreshRate) Hz" }
        # chip, BIOS placa video
        $chip = ''; $bios = ''
        if ($r) {
            $chip = Rs $r.'HardwareInformation.ChipType'; if ($chip -notmatch '^[\x20-\x7E]{2,60}$') { $chip = '' }
            $bios = Rs $r.'HardwareInformation.BiosString'; if ($bios -notmatch '^[\x20-\x7E]{2,80}$') { $bios = '' }
        }
        $hw = @($(if ($chip) { "chip $chip" }), $(if ($bios) { "BIOS $bios" })) | Where-Object { $_ }
        # PCIe: generatia si latimea (curent / maxim)
        $pcie = ''
        try {
            $gen = @{ 1 = '1.0'; 2 = '2.0'; 3 = '3.0'; 4 = '4.0'; 5 = '5.0'; 6 = '6.0' }
            $pp = @{}
            foreach ($k in 'CurrentLinkSpeed', 'CurrentLinkWidth', 'MaxLinkSpeed', 'MaxLinkWidth') {
                $pp[$k] = (Get-PnpDeviceProperty -InstanceId $a.PNPDeviceID -KeyName "DEVPKEY_PciDevice_$k" -ErrorAction Stop).Data
            }
            if ($pp.MaxLinkWidth) {
                $pcie = "PCIe $($gen[[int]$pp.CurrentLinkSpeed]) x$($pp.CurrentLinkWidth)"
                if ($pp.CurrentLinkSpeed -ne $pp.MaxLinkSpeed -or $pp.CurrentLinkWidth -ne $pp.MaxLinkWidth) {
                    $pcie += " (maxim $($gen[[int]$pp.MaxLinkSpeed]) x$($pp.MaxLinkWidth); in idle placa poate cobori singura viteza)"
                }
            }
        } catch {}
        $kind = $(if ($a.Name -match $igpuRx) { '  [integrata in procesor]' } else { '' })
        $lines = @(($a.Name + $kind), "$vtxt  |  $drv", ($hw -join '  |  '), $pcie, $res) | Where-Object { $_ }
        $out += [pscustomobject]@{ Name = $a.Name; VramMB = [int]($vram / 1MB); Text = ($lines -join "`n") }
    }
    $out
}
$gpuInfo = @(Get-GpuInfo)
$ui.GPU.N = if ($gpuInfo.Count) { ($gpuInfo | ForEach-Object { $_.Text }) -join "`n`n" } else { 'GPU necunoscut' }
$script:gpuVramMB = [int](($gpuInfo | Sort-Object VramMB -Descending | Select-Object -First 1).VramMB)
$mem = @(Get-CimInstance Win32_PhysicalMemory)
$ui.RAM.N = "$($mem.Count) module, $($mem[0].ConfiguredClockSpeed) MHz, total $([math]::Round(($mem | Measure-Object Capacity -Sum).Sum / 1GB)) GB"
function Get-DiskInfo {
    $r = @()
    foreach ($d in Get-PhysicalDisk) {
        $t = ''; try { $tc = ($d | Get-StorageReliabilityCounter).Temperature; if ($tc) { $t = "  $tc C" } } catch {}
        $r += "$($d.FriendlyName) [$($d.MediaType)] $([math]::Round($d.Size / 1GB)) GB$t"
    }
    foreach ($v in (Get-Volume | Where-Object { $_.DriveLetter -and $_.DriveType -eq 'Fixed' })) {
        $r += "$($v.DriveLetter): $([math]::Round($v.SizeRemaining / 1GB)) GB liberi / $([math]::Round($v.Size / 1GB)) GB"
    }
    $r -join "`n"
}
$ui.DISCURI.N = Get-DiskInfo; $ui.DISCURI.L = 'Temp. SSD in dreptul fiecarui disc (daca o ofera)'
$ui.DISCURI.V.Text = "$(@(Get-PhysicalDisk).Count) discuri"
$ui.ANALIZA.N = 'Verifica daca procesorul, placa video sau memoria limiteaza performanta (momentul curent).'
$ui.ANALIZA.V.Text = '...'
$ui.SFATURI.N = 'Verificari rapide (doar informative, nu schimba nimic): RAM la viteza nominala, Hz monitor, Resizable BAR, driver video, stare si spatiu discuri.'
$ui.SFATURI.V.Text = '...'

# ---------- Citire live in fundal (nu mai blocheaza interfata) ----------
$script:sd = [hashtable]::Synchronized(@{})
$script:sd['VramMB'] = [int]$script:gpuVramMB
$rs = [runspacefactory]::CreateRunspace(); $rs.ApartmentState = 'MTA'; $rs.Open()
$rs.SessionStateProxy.SetVariable('sd', $script:sd)
$worker = [powershell]::Create(); $worker.Runspace = $rs
[void]$worker.AddScript({
    $tips = @()
    try {
        $m = @(Get-CimInstance Win32_PhysicalMemory)
        $sp = ($m | Measure-Object Speed -Maximum).Maximum; $cf = ($m | Measure-Object ConfiguredClockSpeed -Maximum).Maximum
        if ($sp -and $cf -and $cf -lt ($sp * 0.9)) { $tips += "RAM ruleaza la $cf MHz, dar modulele sunt de $sp MHz: porneste XMP/EXPO din BIOS." }
    } catch {}
    try {
        $vc = @(Get-CimInstance Win32_VideoController | Where-Object { $_.Name -notmatch 'Basic|Remote' })
        $hz = ($vc | Measure-Object CurrentRefreshRate -Maximum).Maximum
        if ($hz -and $hz -le 60) { $tips += "Monitorul ruleaza la $hz Hz. Daca suporta mai mult: Setari > Sistem > Afisare > Setari avansate." }
        # driver: doar placa dedicata (grafica integrata Radeon/Intel UHD/Iris e ignorata daca exista si una dedicata)
        $dg = @($vc | Where-Object { $_.Name -notmatch 'Radeon\(TM\) Graphics$|Radeon Graphics$|Vega \d+ Graphics|Intel.*(UHD|Iris|HD Graphics)' })
        if ($dg.Count -eq 0) { $dg = $vc }
        foreach ($v in $dg) { if ($v.DriverDate -and ((Get-Date) - $v.DriverDate).Days -gt 365) { $tips += "Driverul placii video ($($v.Name)) are peste 1 an: actualizeaza-l de pe site-ul producatorului." } }
    } catch {}
    try {
        $t = (& nvidia-smi -q -d MEMORY 2>$null) -join "`n"
        if ($t -match 'BAR1 Memory Usage\s*\r?\n\s*Total\s*:\s*(\d+)\s*MiB' -and [int]$Matches[1] -le 256) { $tips += 'Resizable BAR pare oprit: porneste Above 4G Decoding + Resizable BAR din BIOS.' }
    } catch {}
    try {
        foreach ($d in Get-PhysicalDisk) { if ($d.HealthStatus -and $d.HealthStatus -ne 'Healthy') { $tips += "Discul $($d.FriendlyName) are starea '$($d.HealthStatus)': fa backup si verifica-l." } }
        foreach ($v in (Get-Volume | Where-Object { $_.DriveLetter -and $_.DriveType -eq 'Fixed' -and $_.Size -gt 0 })) {
            if (($v.SizeRemaining / $v.Size) -lt 0.10) { $tips += "Discul $($v.DriveLetter): are sub 10% spatiu liber ($([math]::Round($v.SizeRemaining / 1GB)) GB)." } }
    } catch {}
    try {
        if (@(Get-PhysicalDisk | Where-Object { $_.MediaType -eq 'SSD' }).Count -gt 0) {
            $o = (& fsutil behavior query DisableDeleteNotify 2>$null) -join ' '
            if ($o -match 'NTFS\s+DisableDeleteNotify\s*=\s*1') { $tips += 'TRIM pare oprit pe SSD. Ca administrator: fsutil behavior set DisableDeleteNotify 0' }
        }
    } catch {}
    try {
        $dg = Get-CimInstance -Namespace root\Microsoft\Windows\DeviceGuard -ClassName Win32_DeviceGuard -ErrorAction Stop
        if ($dg.VirtualizationBasedSecurityStatus -eq 2) { $tips += 'VBS (securitate prin virtualizare) ruleaza: poate costa 5-10% FPS in jocurile limitate de procesor. Il poti opri din SECURITATE (OPTIONAL), cu protectie mai mica.' }
    } catch {}
    try {
        $hs = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers' -Name HwSchMode -ErrorAction Stop).HwSchMode
        if ($hs -ne 2) { $tips += 'HAGS (GPU Scheduling hardware) e oprit: DLSS Frame Generation are nevoie de el. Il pornesti din GPU SI GAMING.' }
    } catch { $tips += 'HAGS (GPU Scheduling hardware) nu e setat: il pornesti din GPU SI GAMING (testeaza, castigul variaza de la joc la joc).' }
    try {
        $gmv = (Get-ItemProperty 'HKCU:\Software\Microsoft\GameBar' -Name AutoGameModeEnabled -ErrorAction Stop).AutoGameModeEnabled
        if ($gmv -eq 0) { $tips += 'Game Mode e oprit: porneste-l (GPU SI GAMING), NVIDIA si Microsoft il recomanda.' }
    } catch {}
    $sd['Tips'] = $tips
    while ($true) {
        try {
            $d = @{}
            $d.Cpu = [int](Get-CimInstance Win32_Processor | Select-Object -First 1).LoadPercentage
            $os = Get-CimInstance Win32_OperatingSystem
            $d.Tot = $os.TotalVisibleMemorySize / 1MB; $d.Use = $d.Tot - $os.FreePhysicalMemory / 1MB
            $d.Gpu = $null
            if (Get-Command nvidia-smi -ErrorAction SilentlyContinue) {
                try { $q = & nvidia-smi --query-gpu=utilization.gpu,temperature.gpu,memory.used,memory.total,clocks.gr,clocks.mem,power.draw,fan.speed --format=csv,noheader,nounits 2>$null
                      if ($q) { $p = (@($q)[0]) -split ',\s*'
                                $num = { param($x) $v = 0.0; if ([double]::TryParse(([string]$x).Trim(), [Globalization.NumberStyles]::Float, [Globalization.CultureInfo]::InvariantCulture, [ref]$v)) { $v } else { $null } }
                                $d.Gpu = @{ Load = [int]$p[0]; Temp = [int]$p[1]; MU = [int]$p[2]; MT = [int]$p[3]
                                            Clk = (& $num $p[4]); MClk = (& $num $p[5]); Pw = (& $num $p[6]); Fan = (& $num $p[7]); FanU = '%' } } } catch {}
            }
            if (-not $d.Gpu) {
                # AMD / Intel: contoare Windows (Task Manager). Alege placa cu cea mai multa memorie dedicata folosita.
                try {
                    $am = @(Get-CimInstance Win32_PerfFormattedData_GPUPerformanceCounters_GPUAdapterMemory -ErrorAction Stop)
                    $best = $am | Sort-Object DedicatedUsage -Descending | Select-Object -First 1
                    if ($best) {
                        $luid = $best.Name -replace '_phys_\d+$', ''
                        $by = @{}
                        foreach ($e in @(Get-CimInstance Win32_PerfFormattedData_GPUPerformanceCounters_GPUEngine -ErrorAction Stop |
                                         Where-Object { $_.Name -like "*$luid*" -and $_.Name -like '*engtype_3D*' })) {
                            if ($e.Name -match '_eng_(\d+)_') { $by[$Matches[1]] = [double]$by[$Matches[1]] + [double]$e.UtilizationPercentage }
                        }
                        $load = 0; if ($by.Count) { $load = [int][math]::Min(100, ($by.Values | Measure-Object -Maximum).Maximum) }
                        $d.Gpu = @{ Load = $load; Temp = $null; MU = [int]($best.DedicatedUsage / 1MB); MT = [int]$sd['VramMB'] }
                    }
                } catch {}
            }
            $d.Ct = $null
            foreach ($ns in 'root/LibreHardwareMonitor', 'root/OpenHardwareMonitor') {
                try { $s = Get-CimInstance -Namespace $ns -ClassName Sensor -ErrorAction Stop |
                           Where-Object { $_.SensorType -eq 'Temperature' -and $_.Name -match 'CPU|Tctl|Package|Tdie' } | Select-Object -First 1
                      if ($s) { $d.Ct = [int]$s.Value; break } } catch {}
            }
            if ($null -eq $d.Ct) { try { $t = Get-CimInstance -Namespace root/wmi -ClassName MSAcpi_ThermalZoneTemperature -ErrorAction Stop | Select-Object -First 1
                                         if ($t) { $d.Ct = [int]($t.CurrentTemperature / 10 - 273.15) } } catch {} }
            if ($d.Gpu -and $null -eq $d.Gpu.Temp) {
                foreach ($ns in 'root/LibreHardwareMonitor', 'root/OpenHardwareMonitor') {
                    try { $gs = @(Get-CimInstance -Namespace $ns -ClassName Sensor -ErrorAction Stop |
                                  Where-Object { $_.SensorType -eq 'Temperature' -and $_.Identifier -match 'gpu' })
                          $gt = $gs | Where-Object { $_.Name -match 'GPU Core' } | Select-Object -First 1
                          if (-not $gt) { $gt = $gs | Select-Object -First 1 }
                          if ($gt) { $d.Gpu.Temp = [int]$gt.Value; break } } catch {}
                }
            }
            # Frecvente, consum si ventilator pe AMD / Intel (sau ce lipseste pe NVIDIA): din LibreHardwareMonitor, daca ruleaza
            if ($d.Gpu -and ($null -eq $d.Gpu.Clk -or $null -eq $d.Gpu.Pw -or $null -eq $d.Gpu.Fan)) {
                foreach ($ns in 'root/LibreHardwareMonitor', 'root/OpenHardwareMonitor') {
                    try {
                        $all = @(Get-CimInstance -Namespace $ns -ClassName Sensor -ErrorAction Stop | Where-Object { $_.Identifier -match '^/gpu' })
                        if (-not $all.Count) { continue }
                        # placa cea mai incarcata (nu grafica integrata, daca exista una dedicata)
                        $grp = $all | Group-Object { ($_.Identifier -split '/')[1..2] -join '/' } | Sort-Object {
                            $l = $_.Group | Where-Object { $_.SensorType -eq 'Load' -and $_.Name -eq 'GPU Core' } | Select-Object -First 1
                            $m = $_.Group | Where-Object { $_.SensorType -eq 'SmallData' -and $_.Name -match 'Memory Total|Dedicated Memory Total' } | Select-Object -First 1
                            [double]$(if ($m) { $m.Value } else { 0 }) * 1000 + [double]$(if ($l) { $l.Value } else { 0 })
                        } -Descending | Select-Object -First 1
                        $sg = $grp.Group
                        $pick = { param($type, $rx) $sg | Where-Object { $_.SensorType -eq $type -and $_.Name -match $rx } | Select-Object -First 1 }
                        if ($null -eq $d.Gpu.Clk) { $x = & $pick 'Clock' 'Core'; if ($x) { $d.Gpu.Clk = [double]$x.Value } }
                        if ($null -eq $d.Gpu.MClk) { $x = & $pick 'Clock' 'Memory'; if ($x) { $d.Gpu.MClk = [double]$x.Value } }
                        if ($null -eq $d.Gpu.Pw) { $x = & $pick 'Power' 'Package|Total|Board|GPU Power|Core'; if ($x) { $d.Gpu.Pw = [double]$x.Value } }
                        if ($null -eq $d.Gpu.Fan) {
                            $x = & $pick 'Control' 'Fan'
                            if ($x) { $d.Gpu.Fan = [double]$x.Value; $d.Gpu.FanU = '%' }
                            else { $x = & $pick 'Fan' '.'; if ($x) { $d.Gpu.Fan = [double]$x.Value; $d.Gpu.FanU = ' RPM' } }
                        }
                        break
                    } catch {}
                }
            }
            foreach ($k in @($d.Keys)) { $sd[$k] = $d[$k] }
            $sd['Ready'] = $true
        } catch {}
        Start-Sleep -Seconds 4
    }
})
[void]$worker.BeginInvoke()

# Interfata doar afiseaza datele deja citite (foarte ieftin)
function Update-Live {
    $d = $script:sd
    if (-not $d['Ready']) { return }
    $cpu = $d['Cpu']; $g = $d['Gpu']; $ct = $d['Ct']; $rp = [int](100 * $d['Use'] / $d['Tot'])
    $ui.CPU.V.Text = "$cpu%" + $(if ($null -ne $ct) { "   $ct C" } else { '' })
    $ui.CPU.L = "Load $cpu%   Temp " + $(if ($null -ne $ct) { "$ct C" } else { 'n/a (porneste LibreHardwareMonitor)' })
    $ui.RAM.V.Text = ('{0:N1} / {1:N0} GB' -f $d['Use'], $d['Tot'])
    $ui.RAM.L = ('{0:N1} / {1:N1} GB folosit ({2}%)' -f $d['Use'], $d['Tot'], $rp)
    Push-Spark 'CPU' $cpu; Push-Spark 'RAM' $rp; if ($g) { Push-Spark 'GPU' $g.Load }
    if ($g) {
        $ui.GPU.V.Text = "$($g.Load)%" + $(if ($null -ne $g.Temp) { "   $($g.Temp) C" } else { '' })
        $gtxt = if ($null -ne $g.Temp) { "$($g.Temp) C" } else { 'n/a (porneste LibreHardwareMonitor)' }
        $gvr = if ($g.MT) { "$($g.MU)/$($g.MT) MB" } else { "$($g.MU) MB" }
        $ui.GPU.L = "Load $($g.Load)%   Temp $gtxt   VRAM $gvr"
        $ex = @()
        if ($null -ne $g.Clk)  { $ex += "Core $([int]$g.Clk) MHz" }
        if ($null -ne $g.MClk) { $ex += "Memorie $([int]$g.MClk) MHz" }
        if ($null -ne $g.Pw)   { $ex += "Consum $([int]$g.Pw) W" }
        if ($null -ne $g.Fan)  { $ex += "Ventilator $([int]$g.Fan)$($g.FanU)" }
        if ($ex.Count) { $ui.GPU.L += "`n" + ($ex -join '   ') }
        elseif ($g.Temp -eq $null) { $ui.GPU.L += "`nFrecvente, consum, ventilator: porneste LibreHardwareMonitor ca administrator" }
    } else { $ui.GPU.V.Text = 'n/a'; $ui.GPU.L = 'Load/Temp indisponibile pe acest GPU' }
    $msg = 'Nicio limitare acum. Ruleaza un joc si uita-te aici pentru un test real.'; $short = 'OK'
    if ($g -and $cpu -ge 85 -and $g.Load -lt 70)      { $msg = "BOTTLENECK CPU: procesorul ($cpu%) tine placa video la $($g.Load)%."; $short = 'BOTTLENECK CPU' }
    elseif ($g -and $g.Load -ge 95 -and $cpu -lt 80)  { $msg = "GPU la limita ($($g.Load)%): normal in jocuri, procesorul are rezerva."; $short = 'GPU LA LIMITA' }
    elseif ($rp -ge 88)                                { $msg = "RAM aproape plin ($rp%): inchide aplicatii sau adauga memorie."; $short = 'RAM PLIN' }
    $ui.ANALIZA.V.Text = $short; $ui.ANALIZA.L = $msg
    $tp = @($d['Tips'] | Where-Object { $_ })
    if ($tp.Count -gt 0) { $ui.SFATURI.V.Text = "$($tp.Count) de verificat"; $ui.SFATURI.L = ($tp -join "`n") }
    else { $ui.SFATURI.V.Text = 'Totul OK'; $ui.SFATURI.L = 'Nu am gasit nimic de corectat.' }
    if ($script:selKey) { Show-Detail }
}
$tm = New-Object Windows.Threading.DispatcherTimer; $tm.Interval = [TimeSpan]::FromSeconds(2)
$tm.Add_Tick({ try { Update-Live } catch {} }); $tm.Start()

# ---------- Optimizari (foldere pe sectiuni) ----------
$accent = @{ 'AI SI COPILOT' = '#FF4D6D'; 'POWER PLAN' = '#FF8A5B'; 'GPU SI GAMING' = '#FF2E4D'; 'PERFORMANTA WINDOWS' = '#F472B6'
             'PRIVACY' = '#FFB7C5'; 'SECURITATE (OPTIONAL)' = '#B91C1C'; $appGroup = '#FFC857'; 'PRIVACY: WINDOWS AI' = '#FF7AA2'; 'PRIVACY: EDGE AI' = '#FF7AA2'; 'PRIVACY: OFFICE AI' = '#FF7AA2' }
$accent['RETEA'] = '#FF9E7A'; $accent['CURATENIE DISC'] = '#F472B6'; $accent['SERVICII'] = '#FF7AA2'; $accent['FPS BOOST'] = '#FF9F1C'
function Get-GroupIcon($n) {
    if ($n -like 'CURATARE*') { return Emo 0x1F4E6 }
    $m = @{ 'AI SI COPILOT' = 0x1F916; 'PRIVACY: WINDOWS AI' = 0x1F9E0; 'PRIVACY: EDGE AI' = 0x1F310; 'PRIVACY: OFFICE AI' = 0x1F4C4
            'PRIVACY' = 0x1F512; 'POWER PLAN' = 0x26A1; 'GPU SI GAMING' = 0x1F3AE; 'PERFORMANTA WINDOWS' = 0x1F680; 'SECURITATE (OPTIONAL)' = 0x1F6E1; 'RETEA' = 0x1F4E1; 'CURATENIE DISC' = 0x1F9F9; 'SERVICII' = 0x1F527; 'FPS BOOST' = 0x1F525 }
    if ($m.ContainsKey($n)) { Emo $m[$n] } else { Emo 0x1F4C1 }
}
function Update-Count {
    $n = @($script:checks | Where-Object { $_.IsChecked }).Count; $Count.Text = "$n optimizari selectate"
    foreach ($g in $script:groups) {
        $k = @($g.Checks | Where-Object { $_.IsChecked }).Count
        $g.Badge.Text = "$k / $($g.Checks.Count) active"; $g.Badge.Foreground = Br $(if ($k -gt 0) { '#FF6B86' } else { '#8A6A72' })
    }
}
# Logo-ul real al unei aplicatii din Microsoft Store (din manifestul ei)
function Get-AppLogo($pkg) {
    try {
        [xml]$x = Get-Content -LiteralPath (Join-Path $pkg.InstallLocation 'AppxManifest.xml') -Raw -ErrorAction Stop
        $rels = @()
        foreach ($ap in @($x.Package.Applications.Application)) { if ($ap.VisualElements.Square44x44Logo) { $rels += $ap.VisualElements.Square44x44Logo } }
        if ($x.Package.Properties.Logo) { $rels += $x.Package.Properties.Logo }
        foreach ($rel in $rels) {
            $dir = Join-Path $pkg.InstallLocation (Split-Path $rel); $base = [IO.Path]::GetFileNameWithoutExtension($rel)
            $c = @(Get-ChildItem -LiteralPath $dir -Filter "$base*.png" -ErrorAction SilentlyContinue)
            if (-not $c.Count) { continue }
            $best = $null
            foreach ($rx in 'targetsize-48_altform-unplated\.png$', 'targetsize-64_altform-unplated\.png$', 'targetsize-48\.png$', 'scale-200\.png$', 'scale-100\.png$') {
                $best = $c | Where-Object { $_.Name -match $rx } | Select-Object -First 1; if ($best) { break } }
            if (-not $best) { $best = $c | Sort-Object Length -Descending | Select-Object -First 1 }
            return New-Bitmap ([IO.File]::ReadAllBytes($best.FullName))
        }
    } catch {}
    $null
}
function Set-AppLogos($g) {
    $script:logosDone = $true
    $pk = @(); try { $pk = @(Get-AppxPackage -ErrorAction Stop) } catch {}
    foreach ($c in $g.Checks) {
        $t = $c.Tag; if (-not $t.K) { continue }
        $hit = $null; foreach ($pat in $t.K) { $hit = $pk | Where-Object { $_.Name -like $pat -and $_.InstallLocation } | Select-Object -First 1; if ($hit) { break } }
        $panel = $c.Content
        if ($hit) {
            $bmp = Get-AppLogo $hit
            if ($bmp) { $im = New-Object Windows.Controls.Image; $im.Source = $bmp; $im.Width = 30; $im.Height = 30; $im.HorizontalAlignment = 'Left'
                        [Windows.Media.RenderOptions]::SetBitmapScalingMode($im, [Windows.Media.BitmapScalingMode]::HighQuality)
                        $panel.Children.RemoveAt(0); $panel.Children.Insert(0, $im) }
        } else {
            $c.Opacity = 0.55; $c.ToolTip = 'Nu e instalata pe acest PC (nu se schimba nimic daca o bifezi)'
        }
    }
}
function Open-Group($g) {
    $script:cur = $g
    if ($g.Name -like 'CURATARE*' -and -not $script:logosDone) { try { Set-AppLogos $g } catch {} }
    $ViewTitle.Text = $g.Name.ToUpper(); $ViewTitle.Foreground = Br $g.Col
    $ViewScroll.Content = $g.Panel
    $bv = $(if ($g.NoBulk) { 'Collapsed' } else { 'Visible' }); $BtnGrpAll.Visibility = $bv; $BtnGrpNone.Visibility = $bv
    $FolderScroll.Visibility = 'Collapsed'; $FolderView.Visibility = 'Visible'
}
function Close-Group { $ViewScroll.Content = $null; $FolderView.Visibility = 'Collapsed'; $FolderScroll.Visibility = 'Visible'; $script:cur = $null; $BtnGrpAll.Visibility = 'Visible'; $BtnGrpNone.Visibility = 'Visible' }
function Select-Rec  { foreach ($c in $script:checks) { $c.IsChecked = [bool]($c.Tag.S -eq $true -or $c.Tag.L.StartsWith($star)) }; Update-Count }
function Select-All  { foreach ($c in $script:checks) { $c.IsChecked = $true }; Update-Count }
function Select-None { foreach ($c in $script:checks) { $c.IsChecked = $false }; Update-Count }

