# ---------- Manager pornire (comutatoare ca in Task Manager; se aplica imediat, reversibil) ----------
$apr = 'Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved'
$startLoc = @(
    @{ P = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run'; A = "HKCU:\$apr\Run"; N = 'utilizator' },
    @{ P = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run'; A = "HKLM:\$apr\Run"; N = 'sistem' },
    @{ P = 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run'; A = "HKLM:\$apr\Run32"; N = 'sistem 32-bit' })
$startDirs = @(
    @{ D = "$env:APPDATA\Microsoft\Windows\Start Menu\Programs\Startup"; A = "HKCU:\$apr\StartupFolder"; N = 'folder Startup' },
    @{ D = "$env:ProgramData\Microsoft\Windows\Start Menu\Programs\StartUp"; A = "HKLM:\$apr\StartupFolder"; N = 'folder Startup (toti)' })
function Get-StartEnabled($a, $n) {
    try { $v = (Get-ItemProperty -LiteralPath $a -Name $n -ErrorAction Stop).$n; return (($v[0] -band 1) -eq 0) } catch { return $true }
}
function Set-StartEnabled($a, $n, $en) {
    if (-not (Test-Path -LiteralPath $a)) { New-Item $a -Force | Out-Null }
    $b = New-Object byte[] 12; $b[0] = $(if ($en) { 2 } else { 3 })
    Set-ItemProperty -LiteralPath $a -Name $n -Value $b -Type Binary -Force
}
$script:startCbs = @()
$startWrap = New-Object Windows.Controls.WrapPanel
function Add-StartItem($name, $src, $cmd, $apprPath) {
    $cb = New-Object Windows.Controls.CheckBox
    $cb.Width = 408; $cb.Height = 62; $cb.Margin = '0,0,10,10'; $cb.Tag = @{ A = $apprPath; N = $name }
    $sp = New-Object Windows.Controls.StackPanel
    $t1 = TB $name 12 '#F3E6EA' $true; $t1.TextTrimming = 'CharacterEllipsis'; $t1.Margin = '0,0,14,0'
    $t2 = TB "$src  |  $cmd" 10 '#8A6A72' $false; $t2.TextTrimming = 'CharacterEllipsis'; $t2.Margin = '0,3,14,0'
    $sp.Children.Add($t1) | Out-Null; $sp.Children.Add($t2) | Out-Null
    $cb.Content = $sp; $cb.ToolTip = $cmd
    $cb.IsChecked = (Get-StartEnabled $apprPath $name)
    $cb.Add_Click({
        $s = $args[0]; $t = $s.Tag
        try { Set-StartEnabled $t.A $t.N ([bool]$s.IsChecked); Say ("Pornire: $($t.N) -> " + $(if ($s.IsChecked) { 'activ' } else { 'oprit' })) }
        catch { $s.IsChecked = -not $s.IsChecked; Say "FAIL pornire $($t.N): $($_.Exception.Message)" }
        Update-StartBadge
    })
    $startWrap.Children.Add($cb) | Out-Null; $script:startCbs += $cb
}
foreach ($l in $startLoc) {
    if (-not (Test-Path -LiteralPath $l.P)) { continue }
    $k = Get-Item -LiteralPath $l.P
    foreach ($n in $k.GetValueNames()) {
        if (-not $n -or $n -match 'SecurityHealth|Defender') { continue }
        Add-StartItem $n $l.N ([string]$k.GetValue($n)) $l.A
    }
}
foreach ($l in $startDirs) {
    if (-not (Test-Path -LiteralPath $l.D)) { continue }
    foreach ($f in Get-ChildItem -LiteralPath $l.D -File -ErrorAction SilentlyContinue) {
        if ($f.Name -eq 'desktop.ini') { continue }
        Add-StartItem $f.Name $l.N $f.FullName $l.A
    }
}
