# ---------- Dosare speciale: GPU pentru jocuri, Mod joc ----------
function New-FolderTile($g, $icon, $title) {
    $t = New-Object Windows.Controls.Border
    $t.Width = 205; $t.Height = 118; $t.Margin = '0,0,12,12'; $t.CornerRadius = 14; $t.Padding = 14
    $t.BorderThickness = 1; $t.Background = Br '#120609'; $t.BorderBrush = Br '#3A0F1A'; $t.Cursor = [Windows.Input.Cursors]::Hand
    $t.Tag = $g
    $sp = New-Object Windows.Controls.StackPanel
    $fi = Icon $icon 42
    $nm = TB $title 12 $g.Col $true; $nm.TextWrapping = 'Wrap'; $nm.Margin = '0,6,0,2'
    $sp.Children.Add($fi) | Out-Null; $sp.Children.Add($nm) | Out-Null; $sp.Children.Add($g.Badge) | Out-Null
    $t.Child = $sp
    $t.Add_MouseEnter({ $args[0].BorderBrush = Br '#FF7A93' })
    $t.Add_MouseLeave({ $args[0].BorderBrush = Br '#3A0F1A' })
    $t.Add_MouseLeftButtonUp({ Open-Group $args[0].Tag })
    $Folders.Children.Add($t) | Out-Null
}
function New-Row($title, $sub) {
    $cb = New-Object Windows.Controls.CheckBox
    $cb.Width = 408; $cb.Height = 62; $cb.Margin = '0,0,10,10'
    $sp = New-Object Windows.Controls.StackPanel
    $t1 = TB $title 12 '#F3E6EA' $true; $t1.TextTrimming = 'CharacterEllipsis'; $t1.Margin = '0,0,14,0'
    $t2 = TB $sub 10 '#8A6A72' $false; $t2.TextTrimming = 'CharacterEllipsis'; $t2.Margin = '0,3,14,0'
    $sp.Children.Add($t1) | Out-Null; $sp.Children.Add($t2) | Out-Null
    $cb.Content = $sp; $cb.ToolTip = $sub
    $cb
}
function New-PillBtn($text) {
    $b = New-Object Windows.Controls.Button
    $b.Style = $w.FindResource('Pill'); $b.Content = $text; $b.Background = Br '#2A1219'
    $b.BorderBrush = Br '#FF2E4D'; $b.BorderThickness = 1; $b.FontSize = 12; $b.Padding = '16,8'; $b.Margin = '0,0,0,12'
    $b.HorizontalAlignment = 'Left'
    $b
}

