function Update-GpuBadge { $gpuG.Badge.Text = "$(@($script:gpuCbs | Where-Object { $_.IsChecked }).Count) jocuri pe GPU dedicat" }
function Add-GpuItem($path) {
    $cb = New-Row ([IO.Path]::GetFileName($path)) $path
    $cb.Tag = $path; $cb.IsChecked = $true
    $cb.Add_Click({
        $s = $args[0]
        try {
            if ($s.IsChecked) {
                if (-not (Test-Path $script:gpuKey)) { New-Item $script:gpuKey -Force | Out-Null }
                Set-ItemProperty -LiteralPath $script:gpuKey -Name $s.Tag -Value 'GpuPreference=2;' -Type String -Force
                Say "GPU: $([IO.Path]::GetFileName($s.Tag)) -> performanta inalta"
            } else {
                Remove-ItemProperty -LiteralPath $script:gpuKey -Name $s.Tag -ErrorAction SilentlyContinue
                Say "GPU: $([IO.Path]::GetFileName($s.Tag)) -> setare Windows implicita"
            }
        } catch { $s.IsChecked = -not $s.IsChecked; Say "FAIL GPU: $($_.Exception.Message)" }
        Update-GpuBadge
    })
    $gpuWrap.Children.Add($cb) | Out-Null; $script:gpuCbs += $cb
}
if (Test-Path $script:gpuKey) {
    $gk = Get-Item -LiteralPath $script:gpuKey
    foreach ($n in $gk.GetValueNames()) { if ($n -and ([string]$gk.GetValue($n)) -match 'GpuPreference=2') { Add-GpuItem $n } }
}
