function Find-Game {
    $re = '\\steamapps\\common\\|\\Epic Games\\|\\GOG Galaxy\\Games\\|\\GOG Games\\|\\Riot Games\\|\\XboxGames\\|\\Ubisoft Game Launcher\\games\\|\\EA Games\\|\\Origin Games\\|\\Rockstar Games\\'
    $skip = 'Launcher|Helper|Riot Client|CrashHandler|Crash Handler|Installer|Setup|Redist|vc_redist'
    $mine = @($script:gpuCbs | Where-Object { $_.IsChecked } | ForEach-Object { $_.Tag })
    foreach ($p in Get-Process -ErrorAction SilentlyContinue) {
        if ($p.WorkingSet64 -lt 300MB) { continue }
        try { $pa = $p.Path } catch { continue }
        if (-not $pa -or [IO.Path]::GetFileName($pa) -match $skip) { continue }
        if ($pa -match $re -or $mine -contains $pa) { return $p }
    }
    return $null
}
$gmTimer = New-Object Windows.Threading.DispatcherTimer; $gmTimer.Interval = [TimeSpan]::FromSeconds(6)
$gmTimer.Add_Tick({
    if (-not $script:gm.On) { return }
    try {
        $g = Find-Game
        if ($g) {
            $script:gm.Idle = 0
            if ($script:gm.Active -and $script:gm.Purge -and ((Get-Date) - $script:gm.LastPurge).TotalSeconds -ge 30) {
                # ca ISLC: doar cand memoria libera scade sub 1 GB si standby are peste 1 GB
                try {
                    $pm = Get-CimInstance Win32_PerfFormattedData_PerfOS_Memory -ErrorAction Stop
                    $sb = [double]$pm.StandbyCacheNormalPriorityBytes + [double]$pm.StandbyCacheReserveBytes + [double]$pm.StandbyCacheCoreBytes
                    if ($pm.FreeAndZeroPageListBytes -lt 1GB -and $sb -gt 1GB) {
                        Initialize-BenchTypes
                        if ([FiveAmSys]::PurgeStandby() -eq 0) { Say ("MOD JOC: memorie standby eliberata ({0:N1} GB)" -f ($sb / 1GB)) }
                        $script:gm.LastPurge = Get-Date
                    }
                } catch {}
            }
            if (-not $script:gm.Active) {
                $script:gm.Active = $true; $script:gm.Closed = @()
                if ($script:gm.Prio) { try { $g.PriorityClass = 'High' } catch {} }
                if ($script:gm.Timer) { try { Initialize-BenchTypes; $tr = [FiveAmSys]::Timer($true); Say ("MOD JOC: timer Windows {0:N1} ms" -f $tr) } catch {} }
                Say "MOD JOC: joc detectat ($($g.ProcessName)), inchid aplicatiile alese..."
                foreach ($cb in $script:gmCbs) {
                    if (-not $cb.IsChecked) { continue }
                    foreach ($pr in @(Get-Process -Name $cb.Tag.N -ErrorAction SilentlyContinue)) {
                        try { $pa = $pr.Path } catch { $pa = $null }
                        if ($pa -and ($script:gm.Closed -notcontains $pa)) { $script:gm.Closed += $pa }
                        try { [void]$pr.CloseMainWindow() } catch {}
                    }
                }
                $script:gm.Kill = (Get-Date).AddSeconds(10)
            } elseif ($script:gm.Kill -and (Get-Date) -gt $script:gm.Kill) {
                $script:gm.Kill = $null
                foreach ($cb in $script:gmCbs) { if ($cb.IsChecked) { Get-Process -Name $cb.Tag.N -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue } }
            }
        } elseif ($script:gm.Active) {
            $script:gm.Idle++
            if ($script:gm.Idle -ge 3) {
                $script:gm.Active = $false; $script:gm.Idle = 0; $script:gm.Kill = $null
                if ($script:gm.Timer) { try { [void][FiveAmSys]::Timer($false) } catch {} }
                foreach ($pa in $script:gm.Closed) { try { Start-Process -FilePath $pa } catch {} }
                Say 'MOD JOC: joc inchis, am redeschis aplicatiile.'; $script:gm.Closed = @()
            }
        }
    } catch {}
})
$gmTimer.Start()

# ---------- Inainte / dupa optimizare (comparatie dupa restart) ----------
$snapFile = "$bkDir\snapshot.json"
function Get-BootInfo {
    try {
        $e = Get-WinEvent -FilterHashtable @{ LogName = 'Microsoft-Windows-Diagnostics-Performance/Operational'; Id = 100 } -MaxEvents 1 -ErrorAction Stop
        $x = [xml]$e.ToXml()
        $ms = [int](($x.Event.EventData.Data | Where-Object { $_.Name -eq 'BootTime' }).'#text')
        return @{ Ms = $ms; At = $e.TimeCreated.ToString('yyyy-MM-dd HH:mm:ss') }
    } catch { return $null }
}
function Get-SnapNow {
    $os = Get-CimInstance Win32_OperatingSystem
    $b = Get-BootInfo
    $free = 0; try { $free = [math]::Round((Get-Volume -DriveLetter ([string]$env:SystemDrive)[0]).SizeRemaining / 1GB, 1) } catch {}
    @{ Procs = @(Get-Process).Count
       RamUsedGB = [math]::Round(($os.TotalVisibleMemorySize - $os.FreePhysicalMemory) / 1MB, 1)
       BootMs = $(if ($b) { $b.Ms } else { 0 }); BootAt = $(if ($b) { $b.At } else { '' })
       LastBoot = $os.LastBootUpTime.ToString('yyyy-MM-dd HH:mm:ss')
       Startup = @($script:startCbs | Where-Object { $_.IsChecked }).Count
       FreeGB = $free }
}
function Show-BeforeAfter {
    if (-not (Test-Path $snapFile)) { return }
    $b = Get-Content $snapFile -Raw | ConvertFrom-Json
    $n = Get-SnapNow
    if ("$($n.LastBoot)" -eq "$($b.LastBoot)") { return }
    Say ''; Say '--- COMPARATIE: inainte -> acum (dupa optimizare si restart) ---'
    if ($b.BootMs -gt 0 -and $n.BootMs -gt 0 -and "$($n.BootAt)" -ne "$($b.BootAt)") {
        Say ('Timp de pornire Windows: {0:N0} s -> {1:N0} s' -f ($b.BootMs / 1000), ($n.BootMs / 1000)) }
    Say "Procese in rulare: $($b.Procs) -> $($n.Procs)"
    Say "RAM folosit: $($b.RamUsedGB) GB -> $($n.RamUsedGB) GB"
    Say "Programe la pornire: $($b.Startup) -> $($n.Startup)"
    if ($b.FreeGB -gt 0 -and $n.FreeGB -gt 0) { Say "Spatiu liber pe disc: $($b.FreeGB) GB -> $($n.FreeGB) GB" }
    Say '(valorile de RAM si procese depind si de ce ai deschis acum)'
    Remove-Item $snapFile -Force -ErrorAction SilentlyContinue
}
$baTimer = New-Object Windows.Threading.DispatcherTimer; $baTimer.Interval = [TimeSpan]::FromSeconds(5)
$baTimer.Add_Tick({ $args[0].Stop(); try { Show-BeforeAfter } catch {} })
$baTimer.Start()

