}
function New-UpdateCmd($new, $target, $noStart) {
    $l = @('@echo off', 'set /a n=0', ':loop', 'ping 127.0.0.1 -n 2 >nul',
           ('move /y "{0}" "{1}" >nul 2>&1' -f $new, $target),
           'if not errorlevel 1 goto done', 'set /a n+=1', 'if %n% lss 40 goto loop', 'exit /b 1', ':done')
    if (-not $noStart) { $l += ('start "" "{0}"' -f $target) }
    $l
}
function Start-UpdateCheck {
    $rs2 = [runspacefactory]::CreateRunspace(); $rs2.Open(); $rs2.SessionStateProxy.SetVariable('sd', $script:sd)
    $uw = [powershell]::Create(); $uw.Runspace = $rs2
    [void]$uw.AddScript({
        param($repo, $cur)
        try {
            [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
            $r = Invoke-RestMethod -Uri "https://api.github.com/repos/$repo/releases/latest" -UseBasicParsing -TimeoutSec 15 `
                                   -Headers @{ 'User-Agent' = '5AMOptimizer'; 'Accept' = 'application/vnd.github+json' }
            $v = [version](([string]$r.tag_name) -replace '^[vV]', '')
            if ($v -gt [version]$cur) {
                $exe = $r.assets | Where-Object { $_.name -eq '5AMOptimizer.exe' } | Select-Object -First 1
                $sha = $r.assets | Where-Object { $_.name -eq '5AMOptimizer.exe.sha256' } | Select-Object -First 1
                $sd['Update'] = @{ Ver = "$v"; Exe = $(if ($exe) { $exe.browser_download_url }); Sha = $(if ($sha) { $sha.browser_download_url })
                                   Notes = [string]$r.body; Page = [string]$r.html_url }
            }
        } catch { $sd['UpdateError'] = $_.Exception.Message }
    }).AddArgument($UpdateRepo).AddArgument($AppVersion)
    [void]$uw.BeginInvoke()
}
function Start-Download {
    if (-not $script:upd.Exe -or -not $script:upd.Sha) { $script:updState = 'failed'; Show-Banner 'Release-ul nu are fisierele necesare. Descarca manual de pe GitHub.' 'err' 'DESCHIDE GITHUB'; return }
    $script:updState = 'downloading'; $script:sd['Dl'] = 'running'
    $rs3 = [runspacefactory]::CreateRunspace(); $rs3.Open(); $rs3.SessionStateProxy.SetVariable('sd', $script:sd)
    $dw = [powershell]::Create(); $dw.Runspace = $rs3
    [void]$dw.AddScript({
        param($exeUrl, $shaUrl, $dest)
        $ProgressPreference = 'SilentlyContinue'
        try {
            [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
            $h = @{ 'User-Agent' = '5AMOptimizer' }
            Invoke-WebRequest -Uri $exeUrl -OutFile $dest -UseBasicParsing -Headers $h -TimeoutSec 300
            $c = (Invoke-WebRequest -Uri $shaUrl -UseBasicParsing -Headers $h -TimeoutSec 30).Content
            if ($c -is [byte[]]) { $c = [Text.Encoding]::ASCII.GetString($c) }
            $expected = ([string]$c).Trim().Split()[0].ToLower()
            $actual = (Get-FileHash -Path $dest -Algorithm SHA256).Hash.ToLower()
            if ($expected -ne $actual) { Remove-Item $dest -Force -ErrorAction SilentlyContinue; throw 'suma de control SHA256 nu corespunde' }
            $sd['Dl'] = 'ok'
        } catch { $sd['Dl'] = 'err: ' + $_.Exception.Message }
    }).AddArgument($script:upd.Exe).AddArgument($script:upd.Sha).AddArgument("$exePath.new")
    [void]$dw.BeginInvoke()
}
function Install-Update {
    try {
        $cmd = Join-Path $env:TEMP '5am_update.cmd'
        Set-Content -Path $cmd -Value (New-UpdateCmd "$exePath.new" $exePath $false) -Encoding ASCII
        $notes = @(([string]$script:upd.Notes) -split "`r?`n" | ForEach-Object { ($_ -replace '^[#\*\-\s]+', '').Trim() } |
                   Where-Object { $_ -and $_ -notmatch '^Full Changelog' } | Select-Object -First 6)
        if (-not (Test-Path $bkDir)) { New-Item $bkDir -ItemType Directory -Force | Out-Null }
        Set-Content -Path $flagFile -Value (@($script:upd.Ver) + $notes) -Encoding UTF8
        Start-Process -FilePath $env:ComSpec -ArgumentList '/c', "`"$cmd`"" -WindowStyle Hidden
        try { $tm.Stop(); $fxT.Stop(); $gmTimer.Stop(); $worker.Stop(); if ($script:ni) { $script:ni.Visible = $false; $script:ni.Dispose() } } catch {}
        [Environment]::Exit(0)
    } catch {
        $script:updState = 'failed'
        Show-Banner "Instalarea a esuat: $($_.Exception.Message)" 'err' 'DESCHIDE GITHUB'
    }
}
$bb.Add_Click({
    if ($isExe -and $script:updState -eq 'found') { Show-Banner "Se descarca v$($script:upd.Ver)..." 'info' $null; Start-Download }
    elseif ($script:upd -and $script:upd.Page) { Start-Process $script:upd.Page }
})
$ut = New-Object Windows.Threading.DispatcherTimer; $ut.Interval = [TimeSpan]::FromSeconds(1)
$ut.Add_Tick({
    $d = $script:sd
    if ($d['Update'] -and $script:updState -eq 'idle') {
        $script:upd = $d['Update']; $script:updState = 'found'
        $noAuto = Test-Path "$bkDir\noautoupdate.txt"
        if ($isExe -and -not $noAuto) { Show-Banner "Versiune noua v$($script:upd.Ver) - se descarca automat..." 'info' $null; Start-Download }
        elseif ($isExe) { Show-Banner "Versiune noua v$($script:upd.Ver) disponibila." 'info' 'ACTUALIZEAZA' }
        else { Show-Banner "Versiune noua v$($script:upd.Ver) pe GitHub." 'info' 'DESCARCA' }
    }
    if ($script:updState -eq 'downloading') {
        $s = [string]$d['Dl']
        if ($s -eq 'ok') {
            if ($BtnApply.IsEnabled) { $script:updState = 'installing'; Show-Banner "Actualizez la v$($script:upd.Ver) si repornesc..." 'info' $null; Install-Update }
            else { Show-Banner 'Actualizare descarcata. Se instaleaza dupa ce termina optimizarea.' 'info' $null }
        } elseif ($s -like 'err*') {
            $script:updState = 'failed'
            Show-Banner "Actualizarea automata a esuat ($s). Descarc-o manual de pe GitHub." 'err' 'DESCHIDE GITHUB'
        }
    }
})
$ut.Start()

# Mesaj dupa actualizare: aplicatia a fost actualizata
if (Test-Path $flagFile) {
    try {
        $fl = @(Get-Content $flagFile -Encoding UTF8 -ErrorAction Stop)
        Remove-Item $flagFile -Force -ErrorAction SilentlyContinue
        if ($fl.Count -and ([string]$fl[0]).Trim() -eq $AppVersion) {
            Show-Banner "Aplicatia a fost actualizata la versiunea $AppVersion!" 'ok' $null
            Say "Aplicatia a fost actualizata la versiunea $AppVersion."
            foreach ($n in ($fl | Select-Object -Skip 1)) { Say "  - $n" }
            $hide = New-Object Windows.Threading.DispatcherTimer; $hide.Interval = [TimeSpan]::FromSeconds(15)
            $hide.Add_Tick({ if ($script:updState -eq 'idle') { $bnr.Visibility = 'Collapsed' }; $hide.Stop() }); $hide.Start()
        }
    } catch {}
}

# ---------- Auto-test (folosit de GitHub Actions; nu afecteaza utilizatorii) ----------
if ($SelfTest) {
    $errs = @()
    if ($script:checks.Count -lt 40) { $errs += "prea putine optimizari: $($script:checks.Count)" }
    foreach ($c in $script:checks) {
        if (-not $c.Tag.L -or -not $c.Tag.Do) { $errs += "optimizare incompleta: $($c.Tag.L)" }
        else { try { [void][scriptblock]::Create($c.Tag.Do.ToString()) } catch { $errs += "cod invalid: $($c.Tag.L)" } }
    }
    if (-not ([version]'1.10.0' -gt [version]'1.9.0')) { $errs += 'comparare versiuni' }
    try {
        $td = Join-Path $env:TEMP ('5am_st_' + [guid]::NewGuid().ToString('N'))
        New-Item $td -ItemType Directory | Out-Null
        Set-Content "$td\app.exe" 'old'; Set-Content "$td\app.exe.new" 'new'
        Set-Content "$td\u.cmd" (New-UpdateCmd "$td\app.exe.new" "$td\app.exe" $true) -Encoding ASCII
        $pr = Start-Process $env:ComSpec -ArgumentList '/c', "`"$td\u.cmd`"" -Wait -PassThru -WindowStyle Hidden
        if (((Get-Content "$td\app.exe" -Raw).Trim() -ne 'new') -or (Test-Path "$td\app.exe.new")) { $errs += 'inlocuirea fisierului exe a esuat' }
        Remove-Item $td -Recurse -Force -ErrorAction SilentlyContinue
    } catch { $errs += "test inlocuire: $($_.Exception.Message)" }
    # benchmark: compilare C#, teste scurte CPU / RAM / disc, scena GPU, statistici FPS, bottleneck
    try {
        Initialize-BenchTypes
        if (-not ([FiveAmBench]::Cpu(1, 300) -gt 0)) { $errs += 'benchmark CPU' }
        if (-not ([FiveAmBench]::Ram(2, 8, 300) -gt 0)) { $errs += 'benchmark RAM' }
        $dk = [FiveAmBench]::Disk((Join-Path $env:TEMP '5am_st_disk.bin'), 64)
        if (-not ($dk[0] -gt 0 -and $dk[1] -gt 0)) { $errs += 'benchmark disc' }
        $tg = New-Object Windows.Controls.Grid; $gs = [FiveAmGpu]::Build($tg, 10); if ($tg.Children.Count -lt 2) { $errs += 'scena GPU' }
        $ftT = [double[]](@(10.0) * 100 + 50.0); $fs = Get-FrameStats $ftT
        if ([math]::Abs($fs.Avg - 96.19) -gt 0.1 -or [math]::Abs($fs.Low1 - 33.33) -gt 0.1) { $errs += "statistici FPS gresite: $($fs.Avg) / $($fs.Low1)" }
        $smp = @(@{ Cpu = 40; Core = 97; Gpu = 60; VU = 7000; VT = 8192; Ram = 50 }, @{ Cpu = 45; Core = 95; Gpu = 62; VU = 7100; VT = 8192; Ram = 52 })
        $bn = Get-Bottleneck $smp 120 240; if ($bn.Kind -ne 'CPU') { $errs += "bottleneck: $($bn.Kind)" }
        Show-Bottleneck $bn 'test'
        if ($script:iconPack.Count -lt 60) { $errs += "iconite 3D incorporate: $($script:iconPack.Count)" }
        if (-not ((Icon (Emo 0x1F680) 30) -is [Windows.Controls.Image])) { $errs += 'iconita 3D nu se afiseaza' }
        $th0 = $script:cfg.Theme; $script:cfg.Theme = 'midnight'; $script:themeCache = @{}
        $bl = Convert-ThemeColor '#FF2E4D'; if ([Convert]::ToInt32($bl.Substring(5, 2), 16) -le [Convert]::ToInt32($bl.Substring(1, 2), 16)) { $errs += "tema midnight: $bl" }
        if ((Convert-ThemeColor '#4ADE80') -ne '#4ADE80') { $errs += 'culorile fixe se schimba cu tema' }
        $script:cfg.Theme = $th0; $script:themeCache = @{}
        $sco = Get-Score; if (-not ($sco.Score -ge 0 -and $sco.Score -le 100 -and $sco.Items.Count -ge 14)) { $errs += "scor: $($sco.Score) / $($sco.Items.Count)" }
        Set-ScoreArc 73; Set-ScoreArc 100; Set-ScoreArc 0
        1..50 | ForEach-Object { Push-Spark 'CPU' ($_ * 2) }
        if ($script:themes.Count -ne 4) { $errs += 'teme' }
        $cd = New-ShareCard 'FiveM_GTAProcess.exe' @{ Avg = 128; Low1 = 90; Low01 = 60 } @{ Avg = 147.3; Low1 = 110; Low01 = 75 }
        if ($cd.PixelWidth -ne 1200) { $errs += 'card' }
        $cf = Save-Card $cd 'selftest'; if (-not (Test-Path $cf) -or (Get-Item $cf).Length -lt 20000) { $errs += 'card PNG' }; Remove-Item $cf -Force -ErrorAction SilentlyContinue
        $prSave = $script:pr.Clone(); $prF = $proofFile; $proofFile = Join-Path $env:TEMP ('5am_st_proof_' + [guid]::NewGuid().ToString('N') + '.json')
        $script:pr = @{ Stage = 'none'; App = ''; Before = $null; After = $null; Boot = ''; Waiting = $true }
        Proof-OnFps 'joc.exe' @{ Avg = 100; Low1 = 70; Low01 = 50 }; $script:pr.Stage = 'restarted'; $script:pr.Waiting = $true
        Proof-OnFps 'joc.exe' @{ Avg = 115; Low1 = 85; Low01 = 60 }
        if ($script:pr.Stage -ne 'done' -or (Get-GainText 100 115) -ne '+15%') { $errs += "dovada: $($script:pr.Stage)" }
        Remove-Item $proofFile -Force -ErrorAction SilentlyContinue; $proofFile = $prF; $script:pr = $prSave
        $benchSave = $benchFile; $benchFile = Join-Path $env:TEMP ('5am_st_bench_' + [guid]::NewGuid().ToString('N') + '.json')
        Add-BenchHistory @{ Type = 'fps'; Date = 'a'; App = 'x.exe'; Avg = 100.5; Low1 = 80 }
        Add-BenchHistory @{ Type = 'stress'; Date = 'b'; CpuMulti = 500; GpuFps = 200 }
        Add-BenchHistory @{ Type = 'fps'; Date = 'c'; App = 'x.exe'; Avg = 120.5; Low1 = 90 }
        $hh = @(Get-BenchHistory); $lf = @($hh | Where-Object { $_.Type -eq 'fps' }) | Select-Object -Last 1
        if ($hh.Count -ne 3 -or [int]$lf.Avg -ne 120) { $errs += "istoric benchmark: $($hh.Count) intrari, ultimul $($lf.Avg)" }
        Remove-Item $benchFile -Force -ErrorAction SilentlyContinue; $benchFile = $benchSave
        $tf = Join-Path $env:TEMP ('5am_st_bk_' + [guid]::NewGuid().ToString('N') + '.json')
        '[[{"Path":"HKCU:\\A","Name":"x"},{"Path":"HKCU:\\B","Name":"y"}],{"Path":"HKCU:\\C","Name":"z"}]' | Set-Content $tf
        if (@(Read-JsonList $tf).Count -ne 3) { $errs += 'Read-JsonList nu desface listele imbricate' }
        Remove-Item $tf -Force -ErrorAction SilentlyContinue
        $tr = [FiveAmSys]::Timer($true); [void][FiveAmSys]::Timer($false); if (-not ($tr -gt 0 -and $tr -le 16)) { $errs += "timer: $tr" }
        [void][FiveAmSys]::PurgeStandby()
    } catch { $errs += "benchmark: $($_.Exception.Message)" }
    Show-Banner 'test' 'ok' 'TEST'
    $out = if ($errs.Count) { @('SELFTEST FAIL') + $errs } else { @("SELFTEST OK - $($script:checks.Count) optimizari, v$AppVersion") }
    Set-Content -Path (Join-Path $env:TEMP '5am_selftest.txt') -Value $out
    try { $worker.Stop(); $script:splash.Close() } catch {}
    [Environment]::Exit($(if ($errs.Count) { 1 } else { 0 }))
}
